window.AponarQuartet2Data={"q2":{"chapters.theme_bn":{"প্রসঙ্গ, পরোক্ষ কথা ও ভাষার সূক্ষ্ম পার্থক্য":"प्रसंग, अप्रत्यक्ष कुरा र भाषाको सूक्ष्म फरक","যুক্তি, বিকল্প দৃষ্টিকোণ ও মতামত গঠন":"तर्क, वैकल्पिक दृष्टिकोण र मत गठन","অভিজ্ঞতা থেকে শেখা ও ভদ্রভাবে মতের পার্থক্য বলা":"अनुभवबाट सिक्नु र विनम्र रूपमा मतको फरक भन्नु","কাজের মূল্যবোধ, সাক্ষাৎকার নেওয়া ও তথ্য সাজানো":"कामको मूल्यबोध, अन्तर्वार्ता लिनु र जानकारी सजाउनु","ঘটনার মোড়, উপমা ও অনুভূতির পরিবর্তন পড়া":"घटनाको मोड, उपमा र अनुभूतिको परिवर्तन पढ्नु","তুলনা, পরিবর্তনের প্রবণতা ও সীমিত সিদ্ধান্ত":"तुलना, परिवर्तनको प्रवृत्ति र सीमित निष्कर्ष"},"chapters.title_bn":{"অধ্যায় ৮ · পেশাদারিত্ব ও সাক্ষাৎকার":"अध्याय ८ · व्यावसायिकता र अन्तर्वार्ता","অধ্যায় ১০ · তথ্য দিয়ে সমাজ বোঝা":"अध्याय १० · जानकारीले समाज बुझ्नु","অধ্যায় ৯ · গল্প, অনুভূতি ও পর্যালোচনা":"अध्याय ९ · कथा, अनुभूति र समीक्षा","অধ্যায় ১২ · চিন্তার পরিবর্তন ও সমাজ":"अध्याय १२ · सोचको परिवर्तन र समाज","অধ্যায় ১১ · শব্দের আড়ালের অর্থ":"अध्याय ११ · शब्द पछाडिको अर्थ","অধ্যায় ৭ · ভিন্ন সংস্কৃতি, নতুন উপলব্ধি":"अध्याय ७ · फरक संस्कृति, नयाँ बोध"},"form_guide.label":{"সম্ভাব্য রূপ":"सम्भाव्य रूप","い-বিশেষণ":"い-विशेषण","な-বিশেষণ":"な-विशेषण","ইচ্ছার রূপ":"इच्छाको रूप"},"form_guide.meaning_bn":{"বর্তমান বা ভবিষ্যতের সাধারণ নেতিবাচক রূপ।":"वर्तमान वा भविष्यको सामान्य नकारात्मक रूप।","ます・です ছাড়া সাধারণ রূপ: বর্তমান, অতীত, ইতিবাচক ও নেতিবাচক। N ও な-বিশেষণের だ কখন বাদ/な/の হবে তা প্রতিটি নিয়মে দেওয়া আছে।":"ます・です बाहेक सामान्य रूप: वर्तमान, अतीत, सकारात्मक र नकारात्मक। N र な-विशेषणको だ कहिले हट्ने/な/の हुने भन्ने कुरा हरेक नियममा दिइएको छ।","বিশেষ্যকে বর্ণনা করলে な লাগে। সব গঠনে な থাকবে না; পাঠের সংযোগ দেখুন।":"संज्ञाको वर्णन गर्दा な लाग्छ। सबै संरचनामा な रहँदैन; पाठको संयोजन हेर्नुहोस्।","সাধারণ অতীত রূপ।":"सामान्य अतीत रूप।","ます-রূপ থেকে শুধু ます বাদ দিন।":"ます-रूपबाट मात्र ます हटाउनुहोस्।","“করি/করব” ধরনের volitional form।":"\"गर्छु/गर्नेछु\" प्रकारको volitional form।","ক্রিয়ার সংযোগের て-form; কোথাও で হয়।":"क्रियाको संयोजनको て-form; कतै で हुन्छ।","কোনো কাজ করতে পারা বোঝায়।":"कुनै काम गर्न सक्नु बुझाउँछ।","বিশেষ্য: ব্যক্তি, বস্তু বা বিষয়ের নাম।":"संज्ञा: व्यक्ति, वस्तु वा विषयको नाम।","い-বিশেষণ, যেমন বড়, দামি। নেতিবাচক ও অতীতে রূপ বদলায়।":"い-विशेषण, जस्तै ठूलो, महँगो। नकारात्मक र अतीतमा रूप बदलिन्छ।","ক্রিয়ার dictionary form; এর মানে সব ক্রিয়া る দিয়ে শেষ হবে না।":"क्रियाको dictionary form; यसको अर्थ सबै क्रिया る ले अन्त्य हुँदैन।","শর্তের ば-form।":"शर्तको ば-form।"},"lessons.examples.bangla":{"সংস্কৃতি আলাদা বলেই আলোচনা করা জরুরি।":"संस्कृति अलग भएकैले छलफल गर्नु जरुरी छ।","তিনি শিক্ষক বলার চেয়ে বরং বন্ধুর মতো।":"उनी शिक्षक भन्नुभन्दा बरु साथी जस्ता छन्।","আগামীকাল হলে সাহায্য করা একেবারে অসম্ভব নয়।":"भोलि भए मद्दत गर्नु एकदमै असम्भव होइन।","বয়স বাড়ার সঙ্গে চিন্তার ধরনও বদলায়।":"उमेर बढ्नेसँगै सोचको तरिका पनि बदलिन्छ।","শিশুটি কাঁদল মনে হতেই সঙ্গে সঙ্গে হাসল।":"बच्चा रोयो जस्तो लाग्ने बित्तिकै तुरुन्तै हाँस्यो।","বিস্তৃত এলাকাজুড়ে জরিপ প্রয়োজন।":"विस्तृत क्षेत्रभरि सर्वेक्षण आवश्यक छ।","খাবারটি যে খেতে পারি না তা নয়, তবে একটু ঝাল।":"खाना खान सक्दिनँ भन्ने होइन, तर अलि पिरो छ।","গত বছরের তুলনায় ব্যবহারকারী বেড়েছে।":"गत वर्षको तुलनामा प्रयोगकर्ता बढेका छन्।","বসন্ত হলেও সকালে এখনো ঠান্ডা।":"वसन्त भए पनि बिहान अझै चिसो छ।","যান বা না যান, জানাবেন।":"जानुहोस् वा नजानुहोस्, जनाउनुहुनेछ।","এভাবে চললে দুর্ঘটনার আশঙ্কা আছে।":"यसरी चलेमा दुर्घटनाको आशंका छ।","বাইরে বের হওয়া মাত্রই বৃষ্টি শুরু হলো।":"बाहिर निस्कने बित्तिकै वर्षा सुरु भयो।","বন্ধুর সঙ্গে দেখা হওয়ার সূত্রে আমার চিন্তা বদলেছে।":"साथीसँग भेट हुने क्रममा मेरो सोच बदलिएको छ।","না করলেও ভদ্রভাবে জানানো ভালো।":"नगरे पनि विनम्र रूपमा जनाउनु राम्रो हुन्छ।","টোকিওর তুলনায় এই শহরে ভাড়া কম।":"टोकियोको तुलनामा यो शहरमा भाडा कम छ।","এইমাত্র বেরিয়েছে, তাই ইতিমধ্যে পৌঁছে যাওয়ার কথা নয়।":"भर्खरै निस्केको छ, त्यसैले पहिले नै पुगिसक्ने कुरा होइन।","বিষয়বস্তু যাচাই করার পরে স্বাক্ষর করুন।":"विषयवस्तु जाँच गरेपछि हस्ताक्षर गर्नुहोस्।","জাপানিতে অভ্যস্ত হওয়ার সঙ্গে কথা বলা আনন্দদায়ক হয়েছে।":"जापानीमा बानी पर्दै जानुसँगै कुरा गर्नु रमाइलो भएको छ।","কথা দিয়েছি বলে এখন আর না করা চলে না।":"वाचा दिएको छु भनेर अब नगर्न मिल्दैन।","এই প্রস্তাব সম্পর্কে আমার প্রশ্ন আছে।":"यो प्रस्तावबारे मेरो प्रश्न छ।","মতবিনিময় অনুষ্ঠানকে উপলক্ষ করে স্থানীয় কাজে যুক্ত হয়েছি।":"मत आदानप्रदान कार्यक्रमलाई अवसर बनाएर स्थानीय काममा जोडिएको छु।","ট্রেন বন্ধ হওয়ায় ট্যাক্সি নেওয়া ছাড়া উপায় ছিল না।":"ट्रेन बन्द भएकाले ट्याक्सी लिनुबाहेक उपाय थिएन।","তিনি হাল না ছেড়ে অনুশীলন চালিয়েছেন।":"उनले हार नमानिकन अभ्यास जारी राखेका छन्।","মনে হচ্ছিল যেন স্বপ্ন দেখছি।":"लागिरहेको थियो जस्तो सपना देखिरहेको छु।","অতিথির চাহিদা অনুযায়ী কক্ষের ব্যবস্থা করব।":"अतिथिको माग अनुसार कोठाको व्यवस्था गर्नेछु।","প্রিয় বন্ধু বলেই সৎভাবে জানাতে চাই।":"प्रिय साथी भएकैले इमानदारीपूर्वक जनाउन चाहन्छु।","প্রতিদিন অনুশীলন করছে, নিশ্চয়ই দক্ষ হবে বলে মনে করি।":"हरेक दिन अभ्यास गर्दैछ, निश्चित रूपमा दक्ष हुनेछ जस्तो लाग्छ।","ব্যাখ্যা পড়েছি ঠিকই, কিন্তু ব্যবহারের পদ্ধতি এখনো বুঝিনি।":"व्याख्या पढेको छु ठिकै, तर प्रयोगको तरिका अझै बुझेको छैन।","দোকানটি সারা বছর খোলা থাকে।":"पसल वर्षभरि खुला रहन्छ।","এত সহজ উপায়ে সব মনে রাখা যাবে, এমন নয় মোটেও।":"यति सजिलो तरिकाले सबै सम्झन सकिन्छ, यस्तो बिल्कुलै होइन।","শুধু বিদেশি শিক্ষার্থী নয়, এলাকার মানুষও অংশ নিতে পারেন।":"मात्र विदेशी विद्यार्थी होइन, क्षेत्रका मानिसहरू पनि भाग लिन सक्छन्।","আমার জানা মতে দোকানটি রবিবারও খোলা থাকে।":"मेरो जानकारी अनुसार पसल आइतबार पनि खुला रहन्छ।","ব্যবস্থার পরিবর্তনের সঙ্গে প্রক্রিয়াও বদলেছে।":"व्यवस्थाको परिवर्तनसँगै प्रक्रिया पनि बदलिएको छ।","টাইফুনের কারণে ট্রেন বন্ধ হওয়ার আশঙ্কা আছে।":"टाइफुनको कारणले ट्रेन बन्द हुने आशंका छ।","তিনি পথঘাট ভালো জানেন, নিশ্চয়ই স্থানীয় বলে মনে হয়।":"उनी बाटोघाटो राम्रोसँग जान्दछन्, निश्चित रूपमा स्थानीय हुन् जस्तो लाग्छ।","জ্বর আছে বলে বিশ্রাম না নিয়ে থাকা চলে না।":"ज्वरो छ भनेर विश्राम नलिई बस्न मिल्दैन।","মতবিনিময় অনুষ্ঠানের মাধ্যমে নতুন বন্ধু হয়েছে।":"मत आदानप्रदान कार्यक्रममार्फत नयाँ साथी भएको छ।","সুস্থ থাকা পর্যন্ত কাজ চালিয়ে যেতে চাই।":"स्वस्थ रहेसम्म काम जारी राख्न चाहन्छु।","সফল হব কি না তা প্রস্তুতির ওপর নির্ভর করে।":"सफल हुनेछु कि छैन त्यो तयारीमाथि निर्भर गर्छ।","আকাশ অন্ধকার হলো মনে হতেই প্রবল বৃষ্টি নামল।":"आकाश अँध्यारो भयो जस्तो लाग्ने बित्तिकै प्रबल वर्षा झर्यो।","বড় ভাই সকালে স্বচ্ছন্দ, এর বিপরীতে ছোট ভাই রাতে স্বচ্ছন্দ।":"ठूलो दाइ बिहान सहज हुन्छन्, यसको विपरीत सानो भाइ राति सहज हुन्छन्।","ছোটবেলায় নদীতে প্রায়ই খেলতাম।":"बाल्यकालमा नदीमा प्रायः खेल्थेँ।","এটি বাস্তব অভিজ্ঞতার ভিত্তিতে লেখা প্রতিবেদন।":"यो वास्तविक अनुभवको आधारमा लेखिएको प्रतिवेदन हो।","বিদেশের জীবন আনন্দের, আবার পরিবারের জন্য মনও খারাপ হয়।":"विदेशको जीवन रमाइलो छ, फेरि परिवारका लागि मन पनि दुख्छ।","অংশ নিন বা না নিন, উত্তর দিন।":"भाग लिनुहोस् वा नलिनुहोस्, उत्तर दिनुहोस्।","এই সমস্যা শুধু জাপানে নয়, অন্য দেশেও আছে।":"यो समस्या मात्र जापानमा होइन, अन्य देशमा पनि छ।","কক্ষটি শান্ত বলার চেয়ে বরং নির্জন লাগে।":"कोठा शान्त भन्नुभन्दा बरु निर्जन लाग्छ।","তিন দিনজুড়ে প্রশিক্ষণ অনুষ্ঠিত হয়েছে।":"तीन दिनभरि तालिम आयोजना भएको छ।","শহর একদিকে সুবিধাজনক, অন্যদিকে জীবনযাত্রার খরচ বেশি।":"शहर एकातिर सुविधाजनक छ, अर्कोतिर जीवनयापनको खर्च बढी छ।","কারণ না জেনে বিচার করা উচিত নয়।":"कारण नजानिकन विचार गर्नु हुँदैन।","জাপানি হলেও সবাই যে কানজিতে দক্ষ তা নয়।":"जापानी भए पनि सबैजना कान्जीमा दक्ष छन् भन्ने होइन।","গ্রাহকসেবার ক্ষেত্রে অন্যের কথা শোনা জরুরি।":"ग्राहक सेवाको क्षेत्रमा अरूको कुरा सुन्नु जरुरी छ।","জাপানি বলতে পারলেও সম্মানসূচক ভাষায় আত্মবিশ্বাস নেই।":"जापानी बोल्न सके पनि सम्मानसूचक भाषामा आत्मविश्वास छैन।","কণ্ঠস্বর শোনা মাত্রই স্বস্তি পেলাম।":"आवाज सुन्ने बित्तिकै राहत पाएँ।","অভিজ্ঞতার সঙ্গে মানানসই কাজের দায়িত্ব দেব।":"अनुभवसँग मिल्दो कामको जिम्मेवारी दिनेछु।","আগে বন্ধুদের সঙ্গে প্রায়ই দীর্ঘ চিঠি লিখতাম।":"पहिले साथीहरूसँग प्रायः लामो चिठी लेख्थेँ।","সুবিধা বেড়েছে ঠিকই, তবু সমস্যা রয়ে গেছে।":"सुविधा बढेको छ ठिकै, तापनि समस्या रहिरहेको छ।","জরিপের ফলকে ভিত্তি করে পরিকল্পনা করেছি।":"सर्वेक्षणको परिणामलाई आधार बनाएर योजना गरेको छु।","চালিয়ে যেতে পেরেছি ঠিক সহকর্মীরা পাশে ছিলেন বলেই।":"जारी राख्न सकेको छु ठिक सहकर्मीहरू साथमा भएकैले।","তিনি এমনভাবে কথা বললেন যেন কিছুই জানেন না।":"उनले यस्तो तरिकाले कुरा गरे जस्तो केही पनि थाहा छैन।","বন্ধুর জন্য চিন্তায় যোগাযোগ না করে থাকতে পারিনি।":"साथीका लागि चिन्तामा सम्पर्क नगरी बस्न सकिनँ।","দামি জিনিস সবসময় ভালো হবে এমন নয়।":"महँगो सामान सधैं राम्रो हुन्छ भन्ने होइन।","সহযোগিতা হলো একই লক্ষ্যে একসঙ্গে কাজ করা।":"सहयोग भनेको एउटै लक्ष्यमा सँगै काम गर्नु हो।","প্রবল বৃষ্টিতে পরিকল্পনা বদলানো ছাড়া উপায় নেই।":"प्रबल वर्षामा योजना बदल्नुबाहेक उपाय छैन।","সূচি ঠিক হওয়া মাত্র জানাব।":"तालिका तय हुने बित्तिकै जनाउनेछु।","বয়স নির্বিশেষে যে কেউ অংশ নিতে পারেন।":"उमेरको बावजुद जो कोही भाग लिन सक्छन्।","কেইগো বলতে অন্যের প্রতি সম্মান প্রকাশের ভাষা বোঝায়।":"敬語 भनेर अरूप्रति सम्मान व्यक्त गर्ने भाषा बुझिन्छ।","জনসংখ্যা বৃদ্ধির সঙ্গে আবাসনের প্রয়োজন বেড়েছে।":"जनसंख्या वृद्धिसँगै आवासको आवश्यकता बढेको छ।","আমি শুধু মতামত জানিয়েছি।":"मैले मात्र मत जनाएको छु।","এবারের সাফল্য আপনাদের পরিশ্রমের ফলই।":"यस पटकको सफलता तपाईंहरूको परिश्रमको फल नै हो।","ঘটনাটি শুনলে না হেসে থাকতে পারি না।":"घटना सुनेमा नहाँसी बस्न सक्दिनँ।","এটি কেবল একটি উদাহরণ।":"यो केवल एउटा उदाहरण हो।"},"lessons.explanation_bn":{"বক্তার দেখা দুটি ঘটনা খুব দ্রুত বদলে যায়। প্রথম অবস্থা বুঝে ওঠার আগেই পরের অবস্থা আসে—এই পরিবর্তনকে তুলে ধরে।":"वक्ताले देखेका दुई घटना धेरै छिटो बदलिन्छन्। पहिलो अवस्था बुझ्न नपाउँदै अर्को अवस्था आउँछ—यो परिवर्तनलाई उठाउँछ।","একটি ঘটনা বড় পরিবর্তন, নতুন অভ্যাস বা সম্পর্কের সূচনা করে। শুধু যেকোনো কারণ নয়, শুরু হওয়ার উপলক্ষকে জোর দেয়।":"एउटा घटनाले ठूलो परिवर्तन, नयाँ बानी वा सम्बन्धको सुरुवात गर्छ। मात्र जुनसुकै कारण होइन, सुरु हुने अवसरलाई जोड दिन्छ।","কাজটি করতে সক্ষম হলেও দায়িত্ব, প্রতিশ্রুতি বা সামাজিক কারণে তা করা গ্রহণযোগ্য নয়। নেতিবাচক ক্রিয়ার সঙ্গে “না করে থাকা চলে না”, অর্থাৎ করতেই হবে।":"काम गर्न सक्षम भए पनि जिम्मेवारी, प्रतिज्ञा वा सामाजिक कारणले त्यो गर्नु स्वीकार्य होइन। नकारात्मक क्रियासँग \"नगरी बस्न मिल्दैन\", अर्थात् गर्नैपर्छ।","কোনো শব্দ বা ধারণাকে সামনে এনে তার অর্থ, সংজ্ঞা বা মূল বৈশিষ্ট্য ব্যাখ্যা করুন। প্রবন্ধ ও ব্যাখ্যামূলক লেখায় মানায়।":"कुनै शब्द वा धारणालाई अगाडि ल्याएर त्यसको अर्थ, परिभाषा वा मूल विशेषता व्याख्या गर्नुहोस्। निबन्ध र व्याख्यात्मक लेखमा सुहाउँछ।","পরিমাণ, ভূমিকা বা গুরুত্বকে সীমিত করে বোঝায়। বক্তা মনে করেন বিষয়টিকে তার চেয়ে বড় করে দেখা ঠিক নয়।":"परिमाण, भूमिका वा महत्त्वलाई सीमित गरेर बुझाउँछ। वक्तालाई लाग्छ विषयलाई त्यसभन्दा ठूलो गरेर हेर्नु ठिक होइन।","Vた-এর সঙ্গে প্রথম কাজ ভালোভাবে করে তারপর সিদ্ধান্ত বা কাজ করুন। Vる-এর সঙ্গে কোনো কাজের ক্ষেত্রে কী গুরুত্বপূর্ণ তা ব্যাখ্যা করুন।":"Vた-सँग पहिलो काम राम्रोसँग गरेर त्यसपछि निर्णय वा काम गर्नुहोस्। Vる-सँग कुनै कामको क्षेत्रमा के महत्त्वपूर्ण छ त्यो व्याख्या गर्नुहोस्।","বাস্তবে ঠিক সেই অবস্থা না হলেও তেমন দেখায় বা অনুভূত হয়। কল্পনা ও উপমা তৈরি করতে ব্যবহার করুন।":"वास्तवमा ठिक त्यो अवस्था नभए पनि त्यस्तै देखिन्छ वा अनुभूति हुन्छ। कल्पना र उपमा बनाउन प्रयोग गर्नुहोस्।","পরিচয় বা আসল কারণকে জোর দিয়ে নির্দিষ্ট করে। বক্তা দৃঢ়ভাবে বলেন, এটিই আসল ব্যাখ্যা। আনুষ্ঠানিক যুক্তি বা মূল্যায়নে উপযোগী।":"परिचय वा वास्तविक कारणलाई जोड दिएर निर्दिष्ट गर्छ। वक्ताले दृढ रूपमा भन्छन्, यही नै वास्तविक व्याख्या हो। औपचारिक तर्क वा मूल्याङ्कनमा उपयोगी छ।","চাহিদা, ক্ষমতা, পরিস্থিতি বা পরিবর্তনের সঙ্গে সামঞ্জস্য রেখে কাজ বা ব্যবস্থা বদলায়। সবার জন্য একই ব্যবস্থা বোঝায় না।":"माग, क्षमता, अवस्था वा परिवर्तनसँग सामञ्जस्य राखेर काम वा व्यवस्था बदलिन्छ। सबैका लागि एउटै व्यवस्था बुझाउँदैन।","একই বিষয় বা পরিস্থিতির দুটি ভিন্ন দিক পাশাপাশি তুলে ধরে। ভালো-মন্দ, সুবিধা-অসুবিধা বা পরস্পর ভিন্ন প্রবণতা তুলনা করা যায়।":"एउटै विषय वा अवस्थाका दुई फरक पक्ष सँगसँगै उठाउँछ। राम्रो-नराम्रो, सुविधा-असुविधा वा परस्पर फरक प्रवृत्ति तुलना गर्न सकिन्छ।","একটি বড় পরিবর্তন বা ঘটনার সঙ্গে সম্পর্কিত আরেকটি পরিবর্তন ঘটে। সামাজিক প্রবণতা, নীতি ও সংখ্যা ব্যাখ্যায় উপযোগী।":"एउटा ठूलो परिवर्तन वा घटनासँग सम्बन्धित अर्को परिवर्तन घट्छ। सामाजिक प्रवृत्ति, नीति र संख्या व्याख्यामा उपयोगी छ।","আগের অবস্থা বা শর্ত বজায় থাকা পর্যন্ত পরের কথা সত্য। 知[し]っている限[かぎ]り বলতে নিজের জানার সীমার মধ্যেও বোঝায়।":"अघिल्लो अवस्था वा सर्त कायम रहुन्जेल पछिको कुरा सत्य हुन्छ। 知[し]っている限[かぎ]り ले आफूले जानेको सीमाभित्र भन्ने पनि बुझाउँछ।","কারণ বা পরিস্থিতি বিবেচনা করে বক্তা প্রবলভাবে সম্ভাবনা অস্বীকার করেন। এটি বক্তার দৃঢ় বিচার; বৈজ্ঞানিক নিশ্চয়তা দাবি নয়।":"कारण वा अवस्था विचार गरेर वक्ताले प्रबल रूपमा सम्भावना अस्वीकार गर्छन्। यो वक्ताको दृढ विचार हो; वैज्ञानिक निश्चितताको दाबी होइन।","নিয়ম, তথ্য, গবেষণা বা অভিজ্ঞতাকে সিদ্ধান্তের ভিত্তি হিসেবে ব্যবহার করা হয়। অনুমানের বদলে কী ভিত্তির ওপর কাজ হয়েছে তা বলুন।":"नियम, जानकारी, अनुसन्धान वा अनुभवलाई निर्णयको आधारको रूपमा प्रयोग गरिन्छ। अनुमानको सट्टा कुन आधारमा काम भएको छ त्यो भन्नुहोस्।","কাজ বা অবস্থা দীর্ঘ সময়, বিস্তৃত এলাকা বা বহু বিষয়ের পরিসরজুড়ে চলেছে বোঝায়। পরিসরের বিস্তারকে গুরুত্ব দেয়।":"काम वा अवस्था लामो समय, विस्तृत क्षेत्र वा धेरै विषयको दायराभरि चलिरहेको बुझाउँछ। दायराको विस्तारलाई महत्त्व दिन्छ।","অন্য বিকল্প না থাকায় অনিচ্ছা সত্ত্বেও কাজটি করতে হয়। বাইরের পরিস্থিতি বা বাস্তব সীমাবদ্ধতা বক্তাকে বাধ্য করে।":"अर्को विकल्प नभएकाले अनिच्छा भए तापनि काम गर्नुपर्छ। बाहिरको अवस्था वा वास्तविक सीमाले वक्तालाई बाध्य पार्छ।","আবেগ বা প্রবল স্বাভাবিক তাড়নায় কাজটি না করে থাকা যায় না। নিজের অনুভূতি বা সহজে বোঝা প্রতিক্রিয়া প্রকাশে মানায়।":"भावना वा प्रबल स्वाभाविक आवेगमा काम नगरी बस्न सकिँदैन। आफ्नो अनुभूति वा सजिलै बुझिने प्रतिक्रिया व्यक्त गर्न सुहाउँछ।","একটি শ্রেণির বাইরে একই কথা আরও বিস্তৃত শ্রেণিতেও প্রযোজ্য হলে ব্যবহার করুন। পরে も বা 広[ひろ]く-এর মতো বিস্তারের ইঙ্গিত থাকতে পারে।":"एउटा वर्गभन्दा बाहिर उही कुरा अझ फराकिलो वर्गमा पनि लागू हुँदा प्रयोग गर्नुहोस्। पछि も वा 広[ひろ]く जस्ता विस्तारको सङ्केत हुन सक्छ।","আগের তথ্য স্বীকার করেও সীমাবদ্ধতা, ব্যতিক্রম বা সতর্কতা জানান। প্রথম কথাটি মিথ্যা না বলে তাকে শর্তসাপেক্ষ করেন।":"अघिल्लो जानकारी स्वीकार गरे पनि सीमा, अपवाद वा सावधानी जनाउनुहोस्। पहिलो कुरालाई झूटो नभनी त्यसलाई शर्तसापेक्ष बनाउनुहुन्छ।","আগের কাজ ঘটার সঙ্গে সঙ্গেই অপ্রত্যাশিত পরিবর্তন বা ঘটনা ঘটে। পরের অংশে সাধারণত পরিকল্পিত নির্দেশ বা ইচ্ছা থাকে না।":"अघिल्लो काम घट्ने बित्तिकै अप्रत्याशित परिवर्तन वा घटना घट्छ। पछिको भागमा सामान्यतया योजनाबद्ध निर्देशन वा इच्छा हुँदैन।","লক্ষণ, পরিস্থিতি বা জানা তথ্য থেকে বক্তা শক্ত অনুমান করেন। সরাসরি দেখা প্রমাণিত ঘটনা বলার বদলে নিজের বিচার প্রকাশ পায়।":"लक्षण, अवस्था वा थाहा भएको जानकारीबाट वक्ताले बलियो अनुमान गर्छन्। सीधा देखेको प्रमाणित घटना भन्नुको सट्टा आफ्नो विचार व्यक्त हुन्छ।","ক্রিয়ার ます বাদ দেওয়া রূপে কোনো কাজ শেষ হলে দ্রুত পরের কাজ করার পরিকল্পনা জানায়। বিশেষ্যের সঙ্গে ফল নির্ভর করার অর্থ হয়।":"क्रियाको ます हटाइएको रूपमा कुनै काम सकिएमा छिटो अर्को काम गर्ने योजना जनाउँछ। संज्ञासँग परिणाम निर्भर हुने अर्थ हुन्छ।","একটি পরিস্থিতি সত্য ধরে নিয়েও পরের মতামত বা সীমা বলুন। জোড়ায় AにしてもBにしても হলে উভয় ক্ষেত্রেই একই কথা প্রযোজ্য।":"एउटा अवस्था सत्य मानेर पनि पछिको मत वा सीमा भन्नुहोस्। जोडीमा AにしてもBにしても भए दुवै अवस्थामा एउटै कुरा लागू हुन्छ।","প্রথম বর্ণনাটি পুরো ঠিক নয় মনে করে তার চেয়ে মানানসই দ্বিতীয় বর্ণনা দিন। বিরোধিতা নয়, আরও যথাযথ ভাষায় সংশোধন।":"पहिलो वर्णन पूर्ण रूपमा ठिक छैन लागेर त्यसभन्दा उपयुक्त दोस्रो वर्णन दिनुहोस्। विरोध होइन, अझ यथार्थ भाषामा संशोधन हो।","একটি কারণকে বিশেষ গুরুত্ব দিয়ে ফলের সঙ্গে জুড়ে দেয়। কারণটি দুর্বল নয়; বক্তা সেটিকেই মূল প্রেরণা হিসেবে সামনে আনছেন।":"एउटा कारणलाई विशेष महत्त्व दिएर परिणामसँग जोड्छ। कारण कमजोर होइन; वक्ताले त्यसैलाई मूल प्रेरणाको रूपमा अगाडि ल्याउँदै हुनुहुन्छ।","একটি কাজ বা অবস্থা ঘটানো ছাড়া পরের কাজ ঘটে। লিখিত বা আনুষ্ঠানিক ভাষায় Vないで-এর কাছাকাছি অর্থ।":"एउटा काम वा अवस्था नघटाईकन पछिको काम घट्छ। लिखित वा औपचारिक भाषामा Vないで को नजिकको अर्थ छ।","আগের তথ্য সত্য মেনে নিয়ে পরের অংশে তার প্রত্যাশিত ফল না হওয়ার কথা বলুন। লিখিত বা কিছুটা আনুষ্ঠানিক ব্যাখ্যায় বেশি মানায়।":"अघिल्लो जानकारी सत्य मानेर पछिको भागमा त्यसको अपेक्षित परिणाम नभएको कुरा भन्नुहोस्। लिखित वा केही औपचारिक व्याख्यामा बढी सुहाउँछ।","নেতিবাচক কথাটিকে পুরোপুরি মানতে চান না। সীমিত সক্ষমতা, আংশিক সত্য বা শর্তসাপেক্ষ সম্মতি প্রকাশ করেন।":"नकारात्मक कुरालाई पूर्ण रूपमा मान्न चाहनुहुन्न। सीमित क्षमता, आंशिक सत्य वा शर्तसापेक्ष सहमति व्यक्त गर्नुहुन्छ।","একটি তুলনার মানদণ্ড নির্দিষ্ট করে পরের তথ্যের পার্থক্য দেখায়। হার, দাম, অতীত ও বর্তমান তুলনায় কাজে আসে।":"एउटा तुलनाको मापदण्ड निर्दिष्ट गरेर पछिको जानकारीको फरक देखाउँछ। दर, मूल्य, अतीत र वर्तमानको तुलनामा काम लाग्छ।","একটি পরিবর্তন অগ্রসর হওয়ার সঙ্গে অন্য একটি অবস্থাও ধীরে বদলায়। বয়স, সময় বা অভিজ্ঞতার বৃদ্ধি বোঝাতে সুবিধাজনক।":"एउटा परिवर्तन अगाडि बढ्नेसँगै अर्को अवस्था पनि बिस्तारै बदलिन्छ। उमेर, समय वा अनुभवको वृद्धि बुझाउन सजिलो छ।","কাজ বা অনুভূতির লক্ষ্য বোঝায়। দুটি পক্ষের বিপরীত বৈশিষ্ট্য তুলনা করতেও ব্যবহার হয়; কোন ব্যবহার তা প্রসঙ্গ দেখে ধরুন।":"काम वा अनुभूतिको लक्ष्य बुझाउँछ। दुई पक्षका विपरीत विशेषता तुलना गर्न पनि प्रयोग हुन्छ; कुन प्रयोग हो त्यो प्रसंग हेरेर समात्नुहोस्।","কোনো অভিজ্ঞতা, মাধ্যম বা ব্যক্তির সাহায্যে ফল পাওয়া বোঝায়। সময়ের বিশেষ্যের সঙ্গে পুরো সময়জুড়েও বোঝাতে পারে।":"कुनै अनुभव, माध्यम वा व्यक्तिको मद्दतले परिणाम पाउनु बुझाउँछ। समयको संज्ञासँग पूरा समयभरि पनि बुझाउन सक्छ।","আগের বিষয়টি যাই হোক, পরের ফল বা নিয়ম বদলায় না। বয়স, অভিজ্ঞতা, আবহাওয়া বা অংশগ্রহণের সিদ্ধান্তে ব্যবহার করা যায়।":"अघिल्लो विषय जे भए पनि, पछिको परिणाम वा नियम बदलिँदैन। उमेर, अनुभव, मौसम वा भाग लिने निर्णयमा प्रयोग गर्न सकिन्छ।","ভবিষ্যতে অনাকাঙ্ক্ষিত ফলের সম্ভাবনা বোঝায়। সংবাদ, সতর্কতা ও আনুষ্ঠানিক ব্যাখ্যায় ব্যবহার হয়।":"भविष्यमा अनपेक्षित परिणामको सम्भावना बुझाउँछ। समाचार, चेतावनी र औपचारिक व्याख्यामा प्रयोग हुन्छ।","একটি সাধারণ অনুমান সবার ক্ষেত্রে ঠিক নয়—এই আংশিক নাকচ প্রকাশ করে। কিছু ক্ষেত্রে সত্য হতে পারে, কিন্তু নিশ্চিত নয়।":"एउटा सामान्य अनुमान सबैको अवस्थामा ठिक छैन—यो आंशिक अस्वीकार व्यक्त गर्छ। केही अवस्थामा सत्य हुन सक्छ, तर निश्चित छैन।","আগেকার অভ্যাস বা বারবার ঘটত এমন অভিজ্ঞতা স্মরণ করে বলুন। এতে স্মৃতিকাতর ভাব থাকতে পারে।":"पहिलेको बानी वा बारम्बार घट्ने अनुभव सम्झेर भन्नुहोस्। यसमा स्मृतिकातर भाव हुन सक्छ।"},"lessons.forms":{"必[かなら]ずしも + ইতিবাচক ধারণা + নেতিবাচক predicate":"必[かなら]ずしも + सकारात्मक धारणा + नकारात्मक predicate","Vない・い-বিশেষণくない + ことはない / N・な-বিশেষণでない + ことはない":"Vない・い-विशेषणくない + ことはない / N・な-विशेषणでない + ことはない","Vない-এর ない বাদ + ずにはいられない（する → せずにはいられない）":"Vない-को ない हटाएर + ずにはいられない（する → せずにはいられない）","Plain form + からこそ（N・な-বিশেষণ: だ + からこそ）":"Plain form + からこそ（N・な-विशेषण: だ + からこそ）","V・い-বিশেষণ plain + 一方[いっぽう]で / な-বিশেষণ + な一方[いっぽう]で / N + である一方[いっぽう]で":"V・い-विशेषण plain + 一方[いっぽう]で / な-विशेषण + な一方[いっぽう]で / N + である一方[いっぽう]で","সময়・এলাকা・পরিসর N + にわたって / N + にわたる + N":"समय・क्षेत्र・दायरा N + にわたって / N + にわたる + N","Vる・Vている・Vない + 限[かぎ]り / N・な-বিশেষণである + 限[かぎ]り":"Vる・Vている・Vない + 限[かぎ]り / N・な-विशेषणである + 限[かぎ]り","N + とは + সংজ্ঞা・ব্যাখ্যা":"N + とは + परिभाषा・व्याख्या","Plain form + とはいえ（N・な-বিশেষণে だ-ও বাদ যায়）":"Plain form + とはいえ（N・な-विशेषणमा だ-पनि हट्छ）","Vます-stem + 次第[しだい]（সঙ্গে সঙ্গে） / N + 次第[しだい]だ（নির্ভর）":"Vます-stem + 次第[しだい]（तुरुन्तै） / N + 次第[しだい]だ（निर्भर）","Vない-এর ない বাদ + ざるを得[え]ない（する → せざるを得[え]ない）":"Vない-को ない हटाएर + ざるを得[え]ない（する → せざるを得[え]ない）","V・い-বিশেষণ plain + かのようだ / N・な-বিশেষণ + であるかのようだ":"V・い-विशेषण plain + かのようだ / N・な-विशेषण + であるかのようだ","V・い-বিশেষণ plain + に違[ちが]いない / N・な-বিশেষণ + に違[ちが]いない":"V・い-विशेषण plain + に違[ちが]いない / N・な-विशेषण + に違[ちが]いない","V・い-বিশেষণ plain + ものの / な-বিশেষণ + なものの / N + であるものの":"V・い-विशेषण plain + ものの / な-विशेषण + なものの / N + であるものの","Vた + ものだ（অতীতের স্মৃতি）":"Vた + ものだ（अतीतको स्मृति）","V・い-বিশেষণ plain + わけがない / な-বিশেষণ + なわけがない / N + のわけがない":"V・い-विशेषण plain + わけがない / な-विशेषण + なわけがない / N + のわけがない","Vた + 上[うえ]で（ক্রম） / Vる・Nの + 上[うえ]で（ক্ষেত্র）":"Vた + 上[うえ]で（क्रम） / Vる・Nの + 上[うえ]で（क्षेत्र）","N + に対[たい]して / N + に対[たい]する + N（লক্ষ্য）":"N + に対[たい]して / N + に対[たい]する + N（लक्ष्य）"},"lessons.meaning_bn":{"… করা মাত্রই হঠাৎ":"… गर्ने बित्तिकै अचानक","একদিকে …, অন্যদিকে …":"एकातिर …, अर्कोतिर …","…এর তুলনায়":"…को तुलनामा","যদিও …, তবু …":"यद्यपि …, तापनि …","…কে সূচনা বা উপলক্ষ করে":"…लाई सुरुवात वा अवसर बनाएर","…অনুযায়ী মানিয়ে":"…अनुसार मिलाएर","…জুড়ে বিস্তৃতভাবে":"…भरि विस्तृत रूपमा","… বলতে কী বোঝায়":"… भन्नाले के बुझिन्छ","… না করেই":"… नगरीकनै","… বলার চেয়ে বরং …":"… भन्नुभन्दा बरु …","একেবারে … নয়, তা নয় / কিছুটা সম্ভব":"एकदमै … होइन, त्यस्तो होइन / केही सम्भव छ","… নির্বিশেষে":"…को बावजुद","…কে ভিত্তি করে":"…लाई आधार बनाएर","… হলেই সঙ্গে সঙ্গে / …এর ওপর নির্ভর":"… हुने बित्तिकै तुरुन्तै / …माथि निर्भर","… না করে উপায় নেই":"… नगरी उपाय छैन","…এর প্রতি / এর বিপরীতে":"…प्रति / यसको विपरीत","নিশ্চয়ই … হবে, আমার দৃঢ় ধারণা":"निश्चित रूपमा … हुनेछ, मेरो दृढ धारणा","… হওয়ার কোনো কথাই নয়":"… हुने कुरै छैन","ঠিক … বলেই":"ठिक … भएकैले","… হলো মনে হতেই আবার …":"… भयो जस्तो लाग्ने बित्तिकै फेरि …","…এর সঙ্গে সংশ্লিষ্ট পরিবর্তনে":"…सँग सम्बन्धित परिवर्तनमा","এমন বলা গেলেও":"यस्तो भन्न सकिए पनि","… করার পরে / … করার ক্ষেত্রে":"… गरेपछि / … गर्ने क्षेत्रमा","যতক্ষণ … শর্ত বজায় থাকে":"जतिसम्म … शर्त कायम रहन्छ","একসময় প্রায়ই … করতাম":"एक समय प्रायः … गर्थेँ","…এর মাধ্যমে / …জুড়ে":"…मार्फत / …भरि","… হলেও / এমনকি … ক্ষেত্রেও":"… भए पनि / यहाँसम्म कि … अवस्थामा पनि","যত …, তত পরিবর্তন":"जति …, त्यति परिवर्तन","… না করে থাকতে পারি না":"… नगरी बस्न सक्दिनँ","পরিস্থিতিগত কারণে … করা চলে না":"परिस्थितिगत कारणले … गर्न मिल्दैन","অন্য কিছু নয়, ঠিক …ই":"अरू केही होइन, ठिक …नै","মাত্র …, এর বেশি নয়":"मात्र …, यसभन्दा बढी होइन","শুধু … নয়, অন্যদের ক্ষেত্রেও":"मात्र … होइन, अरूको अवस्थामा पनि","খারাপ কিছু ঘটার আশঙ্কা আছে":"नराम्रो केही घट्ने आशंका छ","সবসময় বা সবার ক্ষেত্রে … নয়":"सधैं वा सबैको अवस्थामा … होइन","মনে হয় যেন …":"लाग्छ जस्तो …"},"lessons.quiz.explanation_bn":{"必[かなら]ずしも + とは限[かぎ]らない সাধারণ অনুমানকে আংশিক নাকচ করে।":"必[かなら]ずしも + とは限[かぎ]らない ले सामान्य अनुमानलाई आंशिक रूपमा नकार्छ।","দুটি নেতিবাচক অংশ সীমিত বা শর্তসাপেক্ষ সক্ষমতা প্রকাশ করে।":"दुईवटा नकारात्मक भागले सीमित वा सर्तसापेक्ष क्षमता व्यक्त गर्छ।","সংখ্যা কম বা সীমিত হিসেবে দেখাতে にすぎない।":"सङ्ख्या कम वा सीमित भनेर देखाउन にすぎない।","する-এর ব্যতিক্রমী ず-রূপ せず।":"する-को अपवादात्मक ず-रूप せず।","বিশ্রাম না নিয়ে কাজ চালানোর অর্থে dictionary form + ことなく।":"आराम नलिई काम जारी राख्ने अर्थमा dictionary form + ことなく।","ব্যবহারকারী বাড়ার সঙ্গে সম্পর্ক রেখে সেবা বেড়েছে।":"प्रयोगकर्ता बढ्दै जाँदा त्यससँगै सेवा पनि बढेको छ।","ব্যর্থতা থেকে নতুন পড়ার পদ্ধতির শুরু হয়েছে।":"असफलताबाट नयाँ अध्ययन विधिको सुरुवात भएको छ।","অভিজ্ঞতা থাকুক বা না থাকুক আবেদন করা যাবে, তাই にかかわらず।":"अनुभव भए पनि नभए पनि आवेदन दिन सकिन्छ, त्यसैले にかかわらず।","প্রথমে আলোচনা শেষ করে পরে সিদ্ধান্ত, তাই Vた + 上[うえ]で।":"पहिले छलफल सकेर पछि निर्णय, त्यसैले Vた + 上[うえ]で।","নদীর পানি উপচে পড়া অনাকাঙ্ক্ষিত সম্ভাবনা, তাই おそれがある।":"नदीको पानी उर्लेर आउने अनपेक्षित सम्भावना छ, त्यसैले おそれがある।","স্তরের সঙ্গে মিলিয়ে বই বদলায়, তাই に応[おう]じて।":"स्तरसँग मिलाएर पुस्तक बदलिन्छ, त्यसैले に応[おう]じて।","উপভাষা কী, তার সংজ্ঞা দেওয়া হচ্ছে।":"बोली भनेको के हो, त्यसको परिभाषा दिइँदैछ।","বুকিং করার পরও প্রত্যাশিতভাবে যাওয়া হয়নি; ものの এই অমিল দেখায়।":"बुकिङ गरे पनि अपेक्षा गरेजस्तो जान सकिएन; ものの ले यो असङ्गति देखाउँछ।","ব্যর্থ হওয়াটিকেই প্রস্তুতির গুরুত্ব বোঝার বিশেষ কারণ করা হয়েছে।":"असफल हुनुलाई नै तयारीको महत्त्व बुझ्ने विशेष कारण बनाइएको छ।","জানালা খোলার সঙ্গে সঙ্গে অপ্রত্যাশিত বাতাস—Vた + とたん।":"झ्याल खोल्ने बित्तिकै अनपेक्षित हावा—Vた + とたん।","পরিশ্রমের ফলই আসল পরিচয়—এই জোরালো মূল্যায়নে にほかならない।":"परिश्रमको फल नै वास्तविक परिचय हो—यो जोडदार मूल्याङ्कनमा にほかならない।","する ব্যতিক্রমীভাবে せざるを得[え]ない হয়।":"する अपवादात्मक रूपमा せざるを得[え]ない हुन्छ।","কাজ ছিল সংস্কৃতি শেখার মাধ্যম, তাই を通[とお]して।":"काम संस्कृति सिक्ने माध्यम थियो, त्यसैले を通[とお]して।","শিক্ষার্থী ছাড়াও শিক্ষক অংশ নেন; সীমা বিস্তৃত হচ্ছে, তাই に限[かぎ]らず।":"विद्यार्थीबाहेक शिक्षक पनि सहभागी हुन्छन्; सीमा विस्तार हुँदैछ, त्यसैले に限[かぎ]らず।","終[お]わります থেকে ます বাদ দিয়ে 次第[しだい]; কাজ শেষ হলেই পরিকল্পিত যোগাযোগ।":"終[お]わります बाट ます हटाएर 次第[しだい]; काम सकिने बित्तिकै योजना अनुसार सम्पर्क।","সস্তা হওয়া মেনেও কেনার সীমা দেখাচ্ছে।":"सस्तो भएको स्वीकार गरे पनि किन्ने सीमा देखाइएको छ।","ব্যাখ্যার ভিত্তি হবে ঘটনা বা তথ্য, তাই に基[もと]づいて।":"व्याख्याको आधार घटना वा तथ्य हुनेछ, त्यसैले に基[もと]づいて।","ফিরে আসার পরপরই আবার বের হওয়া—দ্রুত অবস্থা বদলাচ্ছে।":"फर्किने बित्तिकै फेरि बाहिर जानु—अवस्था छिट्टै बदलिँदैछ।","কথা বলার ধরনকে উপমা দিয়ে বর্ণনা করায় かのように।":"बोल्ने तरिकालाई उपमा दिएर वर्णन गरिएकाले かのように।","関心[かんしん] বিশেষ্যকে বর্ণনা করছে, তাই に対[たい]する।":"関心[かんしん] नामलाई वर्णन गरिरहेको छ, त्यसैले に対[たい]する।","শান্ত হওয়া ও যাতায়াত অসুবিধা—দুটি ভিন্ন দিক, তাই 一方[いっぽう]で।":"शान्त हुनु र यातायातको असुविधा—दुई फरक पक्ष, त्यसैले 一方[いっぽう]で।","অভিজ্ঞতা বাড়ার সঙ্গে আত্মবিশ্বাস বাড়ছে—পরিবর্তনের সহগতি।":"अनुभव बढेसँगै आत्मविश्वास बढ्दैछ—परिवर्तनसँगको सहगति।","রাগের বর্ণনা বদলে বিপাকে পড়াকে বেশি যথাযথ বলা হচ্ছে।":"रिसको वर्णनको सट्टा अप्ठ्यारोमा परेको भन्नु बढी उपयुक्त भनिएको छ।","এখানে বসবাসের শর্ত বজায় থাকাকালীন নিয়ম মানতে হবে।":"यहाँ बसोबासको सर्त कायम रहुन्जेल नियम पालना गर्नुपर्छ।","ব্যস্ততা মেনেও যোগাযোগের প্রয়োজন বোঝানো হয়েছে।":"व्यस्तता स्वीकार गरे पनि सम्पर्कको आवश्यकता बुझाइएको छ।","দুই সপ্তাহজুড়ে সাক্ষাৎকার নেওয়ার বিস্তার বোঝাচ্ছে।":"दुई हप्ताभर अन्तर्वार्ता लिने विस्तार बुझाइएको छ।","আলো জ্বলছে দেখে কেউ আছেন বলে দৃঢ় অনুমান করা হয়েছে।":"बत्ती बलिरहेको देखेर कोही छ भन्ने दृढ अनुमान गरिएको छ।","এটি দেরি করার সামর্থ্যের প্রশ্ন নয়; গুরুত্বপূর্ণ সভায় দেরি করা চলে না।":"यो ढिलो गर्ने क्षमताको प्रश्न होइन; महत्त्वपूर्ण बैठकमा ढिलो गर्नु हुँदैन।","গত মাস হচ্ছে তুলনার ভিত্তিকাল, তাই に比[くら]べて।":"गत महिना तुलनाको आधार अवधि हो, त्यसैले に比[くら]べて।","অতীতের পুনরাবৃত্ত অভ্যাস স্মরণ করতে Vた + ものだ।":"अतीतको दोहोरिने बानी सम्झन Vた + ものだ।","কোনোভাবেই বলার কথা নয়—দৃঢ় অস্বীকারে わけがない।":"कुनै पनि हालतमा भन्ने कुरा होइन—दृढ अस्वीकारमा わけがない।"},"lessons.quiz.options":{"পড়তে একেবারে পারি না, তা নয়":"पढ्नै सक्दिनँ भन्ने होइन","একেবারেই পড়তে পারি না":"पटक्कै पढ्न सक्दिनँ","অবশ্যই নিখুঁতভাবে পড়ি":"अवश्य नै निपुण रूपमा पढ्छु"},"lessons.quiz.prompt":{"দৃঢ় অস্বীকার:「彼[かれ]がそんなことを言[い]う（　）。」":"दृढ अस्वीकार:「彼[かれ]がそんなことを言[い]う（　）。」","「読[よ]めないことはない。」—কোন অর্থ?":"「読[よ]めないことはない。」—कुन अर्थ?","「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—সময়ের বিস্তার।":"「二週間[にしゅうかん]（　）、社員[しゃいん]に話[はなし]を聞[き]いた。」—समयको विस्तार।","する-এর সঠিক রূপ:「心配[しんぱい]（　）にはいられない。」":"する-को सही रूप:「心配[しんぱい]（　）にはいられない。」","「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—পরিবর্তনের সূচনা।":"「失敗[しっぱい]（　）、勉強[べんきょう]の方法[ほうほう]を変[か]えた。」—परिवर्तनको सुरुवात।","「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—মাধ্যম।":"「仕事[しごと]（　）、地域[ちいき]の文化[ぶんか]を学[まな]んだ。」—माध्यम।","「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—দৃঢ় মূল্যায়ন।":"「成功[せいこう]は努力[どりょく]の結果[けっか]（　）。」—दृढ मूल्याङ्कन।","「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—তুলনা।":"「先月[せんげつ]（　）、売上[うりあげ]が下[さ]がった。」—तुलना।","দৃঢ় অনুমান:「電気[でんき]がついている。誰[だれ]かいる（　）。」":"दृढ अनुमान:「電気[でんき]がついている。誰[だれ]かいる（　）。」","「すべて分[わ]かっている（　）話[はな]す。」—যেন সব জানে।":"「すべて分[わ]かっている（　）話[はな]す。」—जस्तो सबै जानेको छ।","「大雨[おおあめ]で川[かわ]があふれる（　）。」—অনাকাঙ্ক্ষিত ঝুঁকি।":"「大雨[おおあめ]で川[かわ]があふれる（　）。」—अनपेक्षित जोखिम।","「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—শর্ত মেনে সীমা।":"「忙[いそが]しい（　）、連絡[れんらく]は必要[ひつよう]だ。」—सर्त स्वीकार गरेर सीमा।","「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—লক্ষ্যবিষয়।":"「環境[かんきょう]問題[もんだい]（　）関心[かんしん]が高[たか]い。」—लक्षित विषय।","শেষ হলেই জানাব:「終[お]わり（　）、連絡[れんらく]します。」":"सकिने बित्तिकै खबर गर्नेछु:「終[お]わり（　）、連絡[れんらく]します。」","「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—ক্রমে পরিবর্তন।":"「経験[けいけん]が増[ふ]える（　）、自信[じしん]もつく。」—क्रमशः परिवर्तन।","「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—কারণে জোর।":"「失敗[しっぱい]した（　）、次[つぎ]は準備[じゅんび]を大切[たいせつ]にする。」—कारणमा जोड।","「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—দুটি দিক।":"「この町[まち]は静[しず]かな（　）、交通[こうつう]が不便[ふべん]です。」—दुई पक्ष।","「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—না করে।":"「休[やす]む（　）、作業[さぎょう]を続[つづ]けた。」—नगरी।","আগে আলোচনা, তারপর সিদ্ধান্ত:「相談[そうだん]（　）上[うえ]で、決[き]めます。」":"पहिले छलफल, त्यसपछि निर्णय:「相談[そうだん]（　）上[うえ]で、決[き]めます。」","「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—শিক্ষার্থীর বাইরেও প্রযোজ্য।":"「学生[がくせい]（　）、先生[せんせい]も参加[さんか]します。」—विद्यार्थीबाहेक पनि लागू हुन्छ।","「帰[かえ]ってきた（　）、また出[で]かけた。」—দ্রুত পালাবদল।":"「帰[かえ]ってきた（　）、また出[で]かけた。」—छिटो परिवर्तन।","する-এর সঠিক রূপ:「中止[ちゅうし]（　）を得[え]ない。」":"する-को सही रूप:「中止[ちゅうし]（　）を得[え]ない。」","「レベル（　）、教材[きょうざい]を変[か]えます。」—মানিয়ে নেওয়া।":"「レベル（　）、教材[きょうざい]を変[か]えます。」—मिलाएर लिने।","সংজ্ঞা:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」":"परिभाषा:「方言[ほうげん]（　）、ある地域[ちいき]で使[つか]われる言葉[ことば]だ。」","「事実[じじつ]（　）、説明[せつめい]してください。」—ভিত্তি।":"「事実[じじつ]（　）、説明[せつめい]してください。」—आधार।","「怒[おこ]っている（　）、困[こま]っているようだ。」—আরও যথাযথ বর্ণনা।":"「怒[おこ]っている（　）、困[こま]っているようだ。」—बढी उपयुक्त वर्णन।","পুরোনো অভ্যাস:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」":"पुरानो बानी:「学生時代[がくせいじだい]は、よく図書館[としょかん]へ（　）ものだ。」","「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—দায়িত্ববোধ।":"「大切[たいせつ]な会議[かいぎ]なので、遅[おく]れる（　）。」—जिम्मेवारीको भावना।","「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—মাত্র দশজন।":"「参加者[さんかしゃ]は十人[じゅうにん]（　）。」—मात्र दस जना।"},"lessons.tip_bn":{"する-এর রূপ せざる; しざる নয়। নিজের আগ্রহে পছন্দ করা কাজের জন্য নয়।":"する-को रूप せざる; しざる होइन। आफ्नो रुचिले रोजेको कामका लागि होइन।","わけではない = পুরোপুরি এমন নয়; わけがない = কোনোভাবেই এমন হওয়ার কথা নয়।":"わけではない = पूर्ण रूपमा यस्तो होइन; わけがない = कुनै हालतमा पनि यस्तो हुने कुरा होइन।","এই পাঠে সংজ্ঞার ব্যবহার; とは思[おも]わなかった-তে বিস্ময়ের ব্যবহার আলাদা।":"यो पाठमा परिभाषाको प्रयोग; とは思[おも]わなかった-मा आश्चर्यको प्रयोग फरक छ।","কারণ জানাতে からにほかならない; শুধু বিশেষ্যের পরিচয় জোর দিতে にほかならない।":"कारण जनाउन からにほかならない; मात्र संज्ञाको परिचयमा जोड दिन にほかならない।","অভিজ্ঞতার মাধ্যমে শেখা এবং সারা বছরজুড়ে—এই দুই ব্যবহার প্রসঙ্গ দেখে আলাদা করুন।":"अनुभवमार्फत सिक्नु र वर्षभरि—यी दुई प्रयोग प्रसंग हेरेर अलग गर्नुहोस्।","যদিও গ্রীষ্ম, তবু পাহাড়ে ঠান্ডা—এই ধরনের স্বীকারের পর সীমা দেখায়।":"यद्यपि गर्मी, तापनि पहाडमा चिसो—यस प्रकारको स्वीकारपछि सीमा देखाउँछ।","だけでなく-এর মতো বিস্তার বোঝায়; “এই সময়ের মধ্যে সীমাবদ্ধ” অর্থের に限[かぎ]り আলাদা।":"だけでなく जस्तै विस्तार बुझाउँछ; “यो समयभित्र सीमित” अर्थको に限[かぎ]り फरक छ।","জোরপূর্বক বাইরের বাধ্যবাধকতা নয়; হাসি, চিন্তা, কান্নার মতো ভেতরের তাড়না প্রধান।":"जबरजस्ती बाहिरको बाध्यता होइन; हाँसो, चिन्ता, रुनु जस्ता भित्री आवेग प्रमुख हुन्छ।","に応[おう]じて শর্ত অনুযায়ী বদলায়; にかかわらず শর্তে বদলায় না।":"に応[おう]じて सर्त अनुसार बदलिन्छ; にかかわらず सर्तमा बदलिँदैन।","遅[おく]れるにしても মানে দেরি হলেও; দেরি করার অনুমতি দেওয়া নয়।":"遅[おく]れるにしても भनेको ढिलो भए पनि; ढिलो गर्ने अनुमति दिनु होइन।","দুটি ঘটনা শুধু পাশাপাশি নয়; সম্পর্কিত পরিবর্তন দেখাতে হবে।":"दुई घटना मात्र सँगसँगै होइनन्; सम्बन्धित परिवर्तन देखाउनुपर्छ।","食[た]べられないことはない = খাওয়া একেবারে অসম্ভব নয়; স্বচ্ছন্দে খেতে পারি এমন জোর নেই।":"食[た]べられないことはない = खानु पटक्कै असम्भव होइन; सजिलै खान सक्छु भन्ने जोड छैन।","নিয়মিত “এর পরে” বলার জন্য てから যথেষ্ট; とたん হঠাৎ ঘটার অনুভূতি দেয়।":"नियमित \"यसपछि\" भन्नका लागि てから पर्याप्त छ; とたん ले अचानक घट्ने अनुभूति दिन्छ।","কিসের সঙ্গে তুলনা করছেন তা পরিষ্কার রাখুন; শুধু সংখ্যা বললেই তুলনা সম্পূর্ণ হয় না।":"कससँग तुलना गर्दै हुनुहुन्छ त्यो स्पष्ट राख्नुहोस्; मात्र संख्या भन्दैमा तुलना पूर्ण हुँदैन।","পরের বিশেষ্যকে বর্ণনা করলে かのようなN; ক্রিয়াকে বর্ণনা করলে かのようにV।":"पछिको संज्ञालाई वर्णन गरेमा かのようなN; क्रियालाई वर्णन गरेमा かのようにV।","রূপ বদলালে অর্থ বদলায়: 確認[かくにん]した上[うえ]で = যাচাইয়ের পরে; 働[はたら]く上[うえ]で = কাজ করার ক্ষেত্রে।":"रूप बदलिए अर्थ बदलिन्छ: 確認[かくにん]した上[うえ]で = जाँच गरेपछि; 働[はたら]く上[うえ]で = काम गर्ने क्षेत्रमा।","মাত্র তিনজন = 三人[さんにん]にすぎない; প্রায় তিনজন = 三人[さんにん]ぐらい—অর্থ আলাদা।":"मात्र तीन जना = 三人[さんにん]にすぎない; करिब तीन जना = 三人[さんにん]ぐらい—अर्थ फरक छ।","আগের ঘটনাটি পরের পরিবর্তনের শুরু; দৈনন্দিন ছোট কারণেও সবসময় ব্যবহার করবেন না।":"अघिल्लो घटना पछिको परिवर्तनको सुरु हो; दैनिक साना कारणमा पनि सधैं प्रयोग नगर्नुहोस्।","Vる + 一方[いっぽう]だ শুধু পরিবর্তন এক দিকেই এগোনো বোঝাতে পারে; এই পাঠে শেষে で আছে।":"Vる + 一方[いっぽう]だ ले परिवर्तन एउटै दिशामा मात्र अघि बढेको बुझाउन सक्छ; यो पाठमा अन्त्यमा で छ।","বাক্যের পরের অংশে আগের শর্ত অনুযায়ী মানিয়ে নেওয়ার সম্পর্ক খুঁজুন।":"वाक्यको पछिको भागमा अघिल्लो शर्त अनुसार मिलाउने सम्बन्ध खोज्नुहोस्।","から সাধারণ কারণ, からこそ সেই কারণকে জোর দেয়। পরে ইতিবাচক উপদেশ বা মূল্যায়ন প্রায়ই আসে।":"から सामान्य कारण, からこそ ले त्यो कारणलाई जोड दिन्छ। पछि सकारात्मक सल्लाह वा मूल्याङ्कन प्रायः आउँछ।","নিশ্চয়তা অনুভব করলেও এটি অনুমান; হুবহু “প্রমাণিত সত্য” নয়।":"निश्चितता अनुभव भए पनि यो अनुमान हो; ठ्याक्कै \"प्रमाणित सत्य\" होइन।","সাধারণ “ভাবছি” অর্থ নয়। দ্রুত পালাবদল; নিজের ইচ্ছাকৃত ধারাবাহিক কাজ বোঝাতে কম মানায়।":"सामान्य \"सोच्दैछु\" अर्थ होइन। छिटो पालो बदलिनु; आफ्नो जानबुझेर गरिएको निरन्तर काम बुझाउन कम सुहाउँछ।","সরাসরি dictionary form লাগে: 休[やす]むことなく; 休[やす]まないことなく লিখবেন না।":"सिधै dictionary form लाग्छ: 休[やす]むことなく; 休[やす]まないことなく नलेख्नुहोस्।","এই পাঠে শর্তের ব্যবহার। 時間[じかん]の限[かぎ]り মানে সময়ের শেষ সীমা পর্যন্ত—প্রসঙ্গ আলাদা।":"यो पाठमा सर्तको प्रयोग। 時間[じかん]の限[かぎ]り भनेको समयको अन्तिम सीमासम्म—सन्दर्भ फरक छ।","পরের অংশে পরিবর্তন দিন; একটি নির্দিষ্ট মুহূর্তের সিদ্ধান্ত বা সরাসরি আদেশ মানায় না।":"पछिको भागमा परिवर्तन दिनुहोस्; एउटा निश्चित क्षणको निर्णय वा सीधा आदेश सुहाउँदैन।","終[お]わり次第[しだい] = শেষ হলেই; 天気[てんき]次第[しだい] = আবহাওয়ার ওপর নির্ভর।":"終[お]わり次第[しだい] = सकिने बित्तिकै; 天気[てんき]次第[しだい] = मौसममा निर्भर।","ভালো ফলের সম্ভাবনায় সাধারণত使[つか]わない; 危険[きけん] বা ক্ষতির পূর্বাভাসে মানায়।":"राम्रो परिणामको सम्भावनामा सामान्यतया 使[つか]わない; 危険[きけん] वा क्षतिको पूर्वानुमानमा सुहाउँछ।","একবারের সাম্প্রতিক ঘটনা নয়। ものだ-এর সাধারণ সত্য বা উপদেশের ব্যবহার থেকে এটি আলাদা।":"एक पटकको हालसालैको घटना होइन। ものだ-को सामान्य सत्य वा सल्लाहको प्रयोगबाट यो अलग छ।","সরাসরি অক্ষমতা できない থেকে আলাদা। 休[やす]まないわけにはいかない মানে বিশ্রাম নিতেই হবে।":"सिधा असक्षमता できない भन्दा फरक छ। 休[やす]まないわけにはいかない भनेको आराम लिनै पर्छ।","একটি নির্দিষ্ট মুহূর্তের জন্য নয়। 一時間[いちじかん]にわたる説明[せつめい] মানে এক ঘণ্টাজুড়ে ব্যাখ্যা।":"एउटा निश्चित क्षणका लागि होइन। 一時間[いちじかん]にわたる説明[せつめい] भनेको एक घण्टाभरको व्याख्या।","দুটি বিকল্পের মধ্যে দ্বিতীয়টি বেশি সঠিক—এই দিকটি খেয়াল রাখুন।":"दुई विकल्पमध्ये दोस्रो बढी सही छ—यो पक्ष ख्याल राख्नुहोस्।","পুরোপুরি অসম্ভব অর্থ নয়। 必[かなら]ずしも-এর সঙ্গে শেষে নেতিবাচক অর্থ রাখুন।":"पूर्ण रूपमा असम्भव भन्ने अर्थ होइन। 必[かなら]ずしも-सँग अन्त्यमा नकारात्मक अर्थ राख्नुहोस्।","বিশেষ্যের আগে に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।":"नामको अघि に対[たい]する: 先生[せんせい]に対[たい]する質問[しつもん]।","単[たん]に “অনুযায়ী” নয়; সিদ্ধান্তের ভিত্তির সঙ্গে দৃঢ় সম্পর্ক আছে।":"単[たん]に “अनुसार” मात्र होइन; निर्णयको आधारसँग दृढ सम्बन्ध छ।","ものの-এর পরে বাস্তব ফল বা অবস্থা দিন। শুধু দুটি কাজের ক্রম বোঝাতে ব্যবহার করবেন না।":"ものの को पछि वास्तविक परिणाम वा अवस्था दिनुहोस्। मात्र दुई कामको क्रम बुझाउन प्रयोग नगर्नुहोस्।"},"scope_bn":{"QUARTET II-এর ৭–১২ অধ্যায়ের থিম অনুসরণে নির্বাচিত ৩৬টি গ্রামারের নিজস্ব সহায়ক অনুশীলন। এটি মূল বইয়ের সম্পূর্ণ গ্রামার সূচি নয়।":"QUARTET II-को ७–१२ अध्यायको थिम अनुसार छनोट गरिएका ३६ Grammar-को आफ्नै सहयोगी अभ्यास। यो मूल किताबको पूर्ण Grammar सूची होइन।"},"study.dialogue":{"ঠিক বলেছেন। এখনই যোগাযোগ করে দেখব।":"ठिक भन्नुभयो। अहिले नै सम्पर्क गरेर हेर्नेछु।","হ্যাঁ। যাচাই করার পরে সিদ্ধান্ত নিই।":"हो। जाँच गरेपछि निर्णय लिऔं।","নির্দেশনার কাগজ বাড়ালে কেমন হয়?":"निर्देशनको कागज बढाए कस्तो हुन्छ?","আজ আপনার বাসায় আসতে পারি?":"आज तपाईंको घरमा आउन सक्छु?","কিছু হয়েছে?":"केही भएको छ?","গ্রাহকসেবার ক্ষেত্রে কোন বিষয়কে গুরুত্ব দেন?":"ग्राहक सेवाको क्षेत्रमा कुन विषयलाई महत्त्व दिनुहुन्छ?","আচ্ছা। তাহলে সুবিধামতো একটি দিন জানাবেন?":"ठिक छ। त्यसो भए सुविधाजनक एउटा दिन जनाउनुहुन्छ?","আগামীকাল একটু সাহায্য করবেন?":"भोलि अलि मद्दत गर्नुहुन्छ?","আগে ব্যবহারকারীদের জিজ্ঞেস করে দেখব?":"पहिले प्रयोगकर्ताहरूलाई सोधेर हेर्छौं?","এই গ্রাফ থেকে কী বোঝা যায়?":"यो ग्राफबाट के बुझ्न सकिन्छ?","রবিবার হলে পারব।":"आइतबार भए सक्नेछु।","এটিও একটি উপায়, তবে ভাষা বদলানোর প্রয়োজনও আছে বলে মনে করি।":"यो पनि एउटा उपाय हो, तर भाषा बदल्ने आवश्यकता पनि छ जस्तो लाग्छ।","তাহলে রবিবার হলে কেমন হয়?":"त्यसो भए आइतबार भए कस्तो हुन्छ?","প্রথমে গ্রাহকের চাহিদা নিশ্চিত করি।":"पहिले ग्राहकको माग निश्चित गर्छु।","স্টেশনে খোঁজ নিয়ে দেখলে কেমন হয়?":"स्टेशनमा खोजी गरेर हेरे कस्तो हुन्छ?","কিছু কথা জিজ্ঞেস করতে পারি?":"केही कुरा सोध्न सक्छु?","একটি গুরুত্বপূর্ণ খাতা হারিয়ে ফেলেছি।":"एउटा महत्त्वपूर्ण नोटबुक हराएको छु।","আগামীকাল কাজ আছে বলে পারব না।":"भोलि काम छ भनेर सक्दिनँ।","দুঃখিত, আজ আমার অন্য কাজ আছে।":"माफ गर्नुहोस्, आज मेरो अर्को काम छ।","অন্য স্কুলেও কি একই রকম হবে?":"अन्य विद्यालयमा पनि एउटै प्रकारको हुनेछ?","ট্রেন ব্যবহারকারী সবচেয়ে বেশি।":"ट्रेन प्रयोगकर्ता सबैभन्दा बढी छन्।","জি, বলুন।":"हजुर, भन्नुहोस्।","শনিবার বিকেল হলে ঠিক আছে।":"शनिबार दिउँसो भए ठिक छ।","শুধু এই জরিপ থেকে তা বিচার করা যায় না।":"मात्र यो सर्वेक्षणबाट त्यो विचार गर्न सकिँदैन।"},"study.kanji":{"বোঝা বা সমাধান":"बुझ्नु वा समाधान","তুলনা":"तुलना","দৃশ্য":"दृश्य","প্রত্যাশা":"अपेक्षा","বৃদ্ধি":"वृद्धि","মিলিত সহযোগিতা":"मिलित सहयोग","বাহিরে প্রকাশ":"बाहिर अभिव्यक्ति","অনুভূতি বা অবস্থা":"अनुभूति वा अवस्था","অতিথি বা ক্রেতা":"अतिथि वा क्रेता","অভ্যস্ত":"बानी परेको","মনের ভাব":"मनको भाव","ধারণা বা চিন্তা":"धारणा वा सोच","বদলানো":"बदल्नु","বিবেচনা":"विचार","ভিন্ন":"फरक","ভরসা":"भरोसा","হ্রাস":"ह्रास","রূপ বা ছাপ":"रूप वा छाप"},"study.listening_answer":{"এ সপ্তাহে প্রশ্ন তৈরি হবে; আগামী সপ্তাহে লাইব্রেরির প্রবেশপথে জরিপ হবে।":"यो हप्ता प्रश्न तयार हुनेछ; आउँदो हप्ता पुस्तकालयको प्रवेशद्वारमा सर्वेक्षण हुनेछ।","জীবনবৃত্তান্ত আনতে হবে; আগামী মঙ্গলবার বেলা ৩টার মধ্যে অফিসে আসতে হবে; পরিবর্তন চাইলে আগের দিনের মধ্যে ফোন করতে হবে।":"जीवनवृत्तान्त ल्याउनुपर्छ; आउँदो मंगलबार दिउँसो ३ बजेभित्र कार्यालयमा आउनुपर्छ; परिवर्तन चाहिए अघिल्लो दिनभित्र फोन गर्नुपर्छ।","শনিবার বেলা ২টা; স্টেশনের সামনের লাইব্রেরি; শুক্রবারের মধ্যে জানাতে হবে।":"शनिबार दिउँसो २ बजे; स्टेशनको अगाडिको पुस्तकालय; शुक्रबारभित्र जनाउनुपर्छ।","মঙ্গলবার বিকেলে পারবেন; সময়সূচি বদলানো যাবে কি না যাচাই করতে বলছেন।":"मंगलबार दिउँसो सक्नुहुन्छ; समयतालिका बदल्न सकिन्छ कि सकिँदैन जाँच गर्न भन्दै हुनुहुन्छ।","সকালে ৬÷১০ = ৬০ শতাংশ; নির্দিষ্ট সময় নেই একজনের। এগুলো অনুশীলনের সংখ্যা।":"बिहान ६÷१० = ६० प्रतिशत; निश्चित समय छैन एकजनाको। यी अभ्यासका संख्या हुन्।","গতকাল দোকানে যে আসনে বসেছিলেন সেখানে; আজ সন্ধ্যায় নিতে যাবেন।":"हिजो पसलमा जुन सिटमा बस्नुभएको थियो त्यहाँ; आज साँझ लिन जानुहुन्छ।"},"study.listening_question":{"ব্যাগ কোথায় পাওয়া গেছে? বক্তা কখন নিতে যাবেন?":"झोला कहाँ भेटिएको छ? वक्ता कहिले लिन जानुहुन्छ?","কী আনতে হবে, কখন আসতে হবে, পরিবর্তন চাইলে কী করবেন?":"के ल्याउनुपर्छ, कहिले आउनुपर्छ, परिवर्तन चाहिए के गर्नुहुन्छ?","সকালে পড়ার অনুপাত কত? নির্দিষ্ট সময় নেই কতজনের?":"बिहान पढ्ने अनुपात कति छ? निश्चित समय छैन कति जनाको?","কখন, কোথায় এবং কত দিনের মধ্যে জানাতে হবে?":"कहिले, कहाँ र कति दिनभित्र जनाउनुपर्छ?","এ সপ্তাহে কী হবে? জরিপ কোথায় এবং কখন হবে?":"यो हप्ता के हुनेछ? सर्वेक्षण कहाँ र कहिले हुनेछ?","বক্তা কোন দিন পারবেন? শ্রোতার কাছে কী অনুরোধ করছেন?":"वक्ता कुन दिन सक्नुहुन्छ? श्रोतासँग के अनुरोध गर्दै हुनुहुन्छ?"},"study.questions":{"সবার কাছে একই ব্যাখ্যা যথেষ্ট নয় কেন?":"सबैका लागि एउटै व्याख्या किन पर्याप्त छैन?","মিনা যাওয়ার আগে কী করেনি?":"मिनाले जानुअघि के गरिनन्?","গ্রাহকের প্রয়োজন অনুযায়ী ব্যাখ্যা মানিয়ে নেওয়া।":"ग्राहकको आवश्यकता अनुसार व्याख्या मिलाउनु।","প্রথমবার আসা ব্যক্তির উদাহরণটি কী বোঝায়?":"पहिलो पटक आएका व्यक्तिको उदाहरणले के बुझाउँछ?","দৃষ্টিকোণ বদলানোর কারণ কী ছিল?":"दृष्टिकोण बदल्ने कारण के थियो?","লেখাটির মূল শিক্ষা কী?":"लेखको मूल शिक्षा के हो?","পরের বাক্যে কাজ থাকার কারণ ও রবিবারের বিকল্প দেওয়ার তথ্য থেকে।":"पछिको वाक्यमा काम रहेको कारण र आइतबारको विकल्प दिने जानकारीबाट।","ট্রেন ব্যবহারকারীর অনুপাত কত এবং কীভাবে পেলেন?":"ट्रेन प्रयोगकर्ताको अनुपात कति छ र कसरी पाउनुभयो?","প্রথমে কাগজ বাড়াতে চেয়েছিল; পরে ব্যবহারকারীর প্রয়োজন বুঝে ভাষা সহজ করেছে।":"पहिले कागज बढाउन चाहेको थियो; पछि प्रयोगकर्ताको आवश्यकता बुझेर भाषा सजिलो बनाएको छ।","খাতা পাওয়া গেছে বলে স্টেশনের খবর আসার পর।":"नोटबुक भेटिएको छ भनेर स्टेशनको समाचार आएपछि।","না; আগামীকাল পারবে না, রবিবার পারবে বলে বিকল্প দিয়েছে।":"होइन; भोलि सक्दैन, आइतबार सक्छ भनेर विकल्प दिएको छ।","ব্যবহারকারীদের সঙ্গে কথা বলে সমস্যাটি শ্রেণিবিভাগের নাম বুঝতে অসুবিধা বলে জানা যায়।":"प्रयोगकर्ताहरूसँग कुरा गरेर समस्या वर्गीकरणको नाम बुझ्न कठिनाइ हो भनेर थाहा हुन्छ।","আমন্ত্রণের ভাষা শুনে সময় ধরে না নিয়ে পরিস্থিতি যাচাই ও আলোচনা করা দরকার।":"निमन्त्रणाको भाषा सुनेर समय तय भएको नठानी अवस्था जाँच र छलफल गर्न आवश्यक छ।","১২÷২০×১০০ = ৬০ শতাংশ।":"१२÷२०×१०० = ६० प्रतिशत।","কোন ঘটনায় ইউয়ের অনুভূতি বদলাল?":"कुन घटनामा युको अनुभूति बदलियो?","প্রথম প্রস্তাব ও শেষ পদক্ষেপ কীভাবে আলাদা?":"पहिलो प्रस्ताव र अन्तिम कदम कसरी अलग छन्?","গ্রাহকের অভিজ্ঞতা ও চাহিদা আলাদা; সে অনুযায়ী ক্রম ও ভাষা বদলাতে হয়।":"ग्राहकको अनुभव र माग अलग छ; त्यस अनुसार क्रम र भाषा बदल्नुपर्छ।","না; খাতা হারিয়ে ইউয়ের অনুভূতির উপমা। かのように সূত্রটি দেখুন।":"होइन; नोटबुक हराएर युको अनुभूतिको उपमा हो। かのように सूत्र हेर्नुहोस्।","কথাগুলো মুছে যাওয়ার বর্ণনাটি কি বাস্তব ঘটনা?":"कुराहरू मेटिएको वर्णन के वास्तविक घटना हो?","বন্ধুর সময় আছে কি না যোগাযোগ করে নিশ্চিত করেনি। দ্বিতীয় ও তৃতীয় বাক্য মিলিয়ে বুঝবেন।":"साथीको समय छ कि छैन सम्पर्क गरेर निश्चित गरिनन्। दोस्रो र तेस्रो वाक्य मिलाएर बुझ्नुहोस्।","難[むずか]しい-এর উদ্দেশ্য কোন তথ্য থেকে নিশ্চিত হলেন?":"難[むずか]しい-को उद्देश्य कुन जानकारीबाट निश्चित हुनुभयो?","এই কথোপকথনে বন্ধু কি সাহায্য একেবারে অস্বীকার করেছে?":"यो वार्तालापमा साथीले के मद्दत एकदमै अस्वीकार गरेको छ?","উত্তরদাতা কেবল একটি ক্লাসের ২০ জন; নমুনা জাতীয় প্রতিনিধিত্ব নিশ্চিত করে না।":"उत्तरदाता केवल एउटा कक्षाका २० जना हुन्; नमुनाले राष्ट्रिय प्रतिनिधित्व निश्चित गर्दैन।","কেন সারা জাপানের বিষয়ে সিদ্ধান্ত নেওয়া যায় না?":"किन सारा जापानको विषयमा निष्कर्ष निकाल्न सकिँदैन?"},"study.reading":{"たとえば-এর উদাহরণ আগের মানিয়ে নেওয়ার বক্তব্যকে স্পষ্ট করে।":"たとえば-को उदाहरणले अघिल्लो मिलाउने भनाइलाई स्पष्ट पार्छ।","পরের কারণ ও বিকল্প দিন থেকে আগের কথার উদ্দেশ্য পরিষ্কার হয়।":"पछिको कारण र वैकल्पिक दिनबाट अघिल्लो कुराको उद्देश्य स्पष्ट हुन्छ।","অন্য দৃষ্টিকোণ থেকে ভাবাই উন্নতির সূচনা হলো।":"अर्को दृष्टिकोणबाट सोच्नु नै उन्नतिको सुरुवात भयो।","একটি ছোট দোকানের ম্যানেজারকে জিজ্ঞেস করলাম, কাজের কোন বিষয়টিকে গুরুত্ব দেন।":"एउटा सानो पसलका म्यानेजरलाई सोधेँ, कामको कुन विषयलाई महत्त्व दिनुहुन्छ।","কাগজ কম থাকা নয়, নামের অর্থ না বোঝা—সমস্যার ব্যাখ্যা বদলাল।":"कागज कम हुनु होइन, नामको अर्थ नबुझ्नु—समस्याको व्याख्या बदलियो।","এই বাক্য গল্পের মোড় বদলায়; আগের উদ্বেগের বিপরীতে ভালো খবর।":"यो वाक्यले कथाको मोड बदल्छ; अघिल्लो चिन्ताको विपरीत राम्रो समाचार।","সমাধান হিসেবে আলোচনা এসেছে; কোনো দেশের সব মানুষকে নিয়ে নিয়ম বলা হয়নি।":"समाधानको रूपमा छलफल आएको छ; कुनै देशका सबै मानिसबारे नियम भनिएको छैन।","শেষ বাক্য ঘটনাটির সাধারণ শিক্ষা; উদাহরণের বাইরে অতিরিক্ত ফল দাবি করা হয়নি।":"अन्तिम वाक्य घटनाको सामान्य शिक्षा हो; उदाहरणबाहिर अतिरिक्त परिणाम दाबी गरिएको छैन।","ক্লাসের অনুশীলনের জন্য ধরে নিই, ২০ শিক্ষার্থীকে যাতায়াতের উপায় জিজ্ঞেস করা হলো।":"कक्षाको अभ्यासका लागि मानौं, २० विद्यार्थीलाई यातायातको उपाय सोधियो।","ম্যানেজার বললেন, “একই ব্যাখ্যা বারবার বলাই যথেষ্ট নয়।”":"म्यानेजरले भन्नुभयो, \"एउटै व्याख्या बारम्बार भन्नु नै पर्याप्त होइन।\"","তার মনে হলো, যেন গুরুত্বপূর্ণ কথাগুলোও হারিয়ে গেছে।":"उनलाई लाग्यो, जस्तो महत्त्वपूर्ण कुराहरू पनि हराएका छन्।","しかし আগের প্রত্যাশার সঙ্গে বাস্তব অবস্থার অমিল আনে।":"しかし ले अघिल्लो अपेक्षासँग वास्तविक अवस्थाको असंगति ल्याउँछ।","এই দৃশ্যে কী বোঝায় বলা হয়েছে; সব ক্ষেত্রে একই অর্থ দাবি করা হয়নি।":"यो दृश्यमा के बुझाउँछ भनिएको छ; सबै अवस्थामा एउटै अर्थ दाबी गरिएको छैन।","খাতাটি হাতে পেয়ে ইউ না হেসে থাকতে পারল না।":"नोटबुक हातमा पाएर यु नहाँसी बस्न सकेनन्।","পরদিন স্টেশন থেকে জানানো হলো খাতাটি পাওয়া গেছে।":"अर्को दिन स्टेशनबाट जनाइयो नोटबुक भेटिएको छ।","দুজন সময়সূচি নিশ্চিত করার গুরুত্ব নিয়ে আলোচনা করল।":"दुवैले समयतालिका निश्चित गर्ने महत्त्वबारे छलफल गरे।","কিন্তু বন্ধু তখন কাজে বের হওয়ার ঠিক আগের অবস্থায় ছিল।":"तर साथी त्यस समयमा काममा निस्कने ठिक अगाडिको अवस्थामा थिए।","তারপর বলল, “কাজ আছে, তবে রবিবার হলে সাহায্য করতে পারব।”":"त्यसपछि भन्यो, \"काम छ, तर आइतबार भए मद्दत गर्न सक्नेछु।\"","এটি অনুশীলনের কাল্পনিক জরিপ; বাস্তব গবেষণা নয়।":"यो अभ्यासको काल्पनिक सर्वेक्षण हो; वास्तविक अनुसन्धान होइन।","বন্ধু বলল, “আগামীকাল একটু কঠিন হবে।”":"साथीले भन्यो, \"भोलि अलि कठिन हुनेछ।\"","প্রথম বাক্যে সমস্যাটি এসেছে; খাতাটির দৈনন্দিন গুরুত্বও জানা গেল।":"पहिलो वाक्यमा समस्या आएको छ; नोटबुकको दैनिक महत्त्व पनि थाहा भयो।","বাসায় পৌঁছানো মাত্র সে বিষয়টি টের পেল।":"घर पुग्ने बित्तिकै उनले विषय थाहा पाए।","অনুরোধের বিষয় ও সময় আগে দেওয়া হয়েছে।":"अनुरोधको विषय र समय पहिले दिइएको छ।","পরদিন সে কোনো যোগাযোগ না করেই বন্ধুর বাসায় গেল।":"अर्को दिन उनी कुनै सम्पर्क नगरी साथीको घरमा गए।","しかし উপসংহারের সীমা নির্দেশ করে।":"しかし ले निष्कर्षको सीमा निर्देशन गर्छ।","মোট ১২+৫+৩=২০; গণনার ভিত্তি একই আছে।":"कुल १२+५+३=२०; गणनाको आधार एउटै छ।","শেষ বাক্য লেখার মূল শিক্ষা।":"अन्तिम वाक्य लेखको मूल शिक्षा हो।","最初[さいしょ]は প্রথম প্রস্তাব চিহ্নিত করছে; এটি চূড়ান্ত সমাধান নয়।":"最初[さいしょ]は ले पहिलो प्रस्तावलाई सङ्केत गर्छ; यो अन्तिम समाधान होइन।","প্রথমে নির্দেশনার কাগজ বাড়ানোর কথা ভাবা হলো।":"पहिले निर्देशनको कागज बढाउने कुरा सोचियो।","এই অভিজ্ঞতার মাধ্যমে মিনা কথার পাশাপাশি পরিস্থিতিও যাচাই করতে শুরু করল।":"यो अनुभवमार्फत मिनाले कुरासँगै अवस्था पनि जाँच गर्न थाले।","কারণ লক্ষ্যগোষ্ঠী কেবল একটি ক্লাস।":"कारण लक्षित समूह केवल एउटा कक्षा हो।","১২ জন ট্রেন, ৫ জন সাইকেল এবং ৩ জন হেঁটে যাওয়ার কথা বলল।":"१२ जनाले ट्रेन, ५ जनाले साइकल र ३ जनाले हिँडेर जाने कुरा भने।","かのように উপমা; বাস্তবে সব কথা মুছে গেছে এমন তথ্য নয়।":"かのように उपमा हो; वास्तवमा सबै कुरा मेटिएको छ भन्ने जानकारी होइन।","聞[き]きました-র প্রশ্নবিষয় দিয়ে পরের উত্তরের কেন্দ্র নির্ধারিত হয়।":"聞[き]きました-को प्रश्न विषयले पछिको उत्तरको केन्द्र निर्धारण हुन्छ।","ট্রেন ব্যবহারকারীর অনুপাত ৬০ শতাংশ।":"ट्रेन प्रयोगकर्ताको अनुपात ६० प्रतिशत छ।","তাই কর্মীরা পরিচিত ভাষায় লেখা নির্দেশনা ব্যবহার করলেন।":"त्यसैले कर्मचारीहरूले परिचित भाषामा लेखिएको निर्देशन प्रयोग गरे।","এখানে 難[むずか]しい কেবল কাজের জটিলতা নাও বোঝাতে পারে।":"यहाँ 難[むずか]しい ले कामको जटिलता मात्र नबुझाउन पनि सक्छ।","を通[とお]して অভিজ্ঞতার মাধ্যমে শেখা; ようになった আচরণের পরিবর্তন।":"を通[とお]して अनुभवको माध्यमबाट सिक्ने; ようになった व्यवहारको परिवर्तन।","に応[おう]じて মানিয়ে নেওয়া; そうです বক্তার কাছ থেকে শোনা তথ্য।":"に応[おう]じて मिलाएर लिने; そうです वक्ताबाट सुनेको जानकारी।","たとたん পৌঁছানোর সঙ্গে হঠাৎ উপলব্ধি বোঝায়।":"たとたん ले पुग्नेसँगै अचानक बोध बुझाउँछ।","গ্রাহকের চাহিদা অনুযায়ী তিনি ব্যাখ্যার ক্রম ও ভাষা বদলান।":"ग्राहकको माग अनुसार उनले व्याख्याको क्रम र भाषा बदल्छन्।","ことなく মানে না করে; মিনার আগেই খবর না দেওয়া এখানে গুরুত্বপূর্ণ।":"ことなく को अर्थ नगरी; मिनाले पहिले नै खबर नदिनु यहाँ महत्त्वपूर्ण छ।","কেন এক বন্ধুকে পরদিন বাসা বদলে সাহায্য করতে বলল।":"केनले एक साथीलाई अर्को दिन घर सर्न मद्दत गर्न भने।","শেষ বাক্য প্রতিবেদকের উপলব্ধি; ম্যানেজারের সরাসরি উদ্ধৃতি নয়।":"अन्तिम वाक्य प्रतिवेदकको बोध हो; म्यानेजरको सीधा उद्धरण होइन।","মনে হলো, মন দিয়ে অন্যের কথা শোনাই আস্থার শুরু।":"लाग्यो, मन दिएर अरूको कुरा सुन्नु नै विश्वासको सुरु हो।","শেষ প্রতিক্রিয়া থেকে স্বস্তি ও আনন্দ বোঝা যায়।":"अन्तिम प्रतिक्रियाबाट राहत र आनन्द बुझ्न सकिन्छ।","প্রথম বাক্যে বলা তথ্যটি আমন্ত্রণের ভাষা; এখনো সময় নির্দিষ্ট হয়নি।":"पहिलो वाक्यमा भनिएको जानकारी निमन्त्रणाको भाषा हो; अझै समय निर्दिष्ट भएको छैन।","কিন্তু ব্যবহারকারীদের সঙ্গে কথা বলে জানা গেল, শ্রেণিবিভাগের নাম বোঝা কঠিন।":"तर प्रयोगकर्ताहरूसँग कुरा गरेर थाहा भयो, वर्गीकरणको नाम बुझ्न कठिन छ।","ইউ প্রতিদিন ব্যবহার করা খাতাটি ট্রেনে ফেলে এল।":"युले हरेक दिन प्रयोग गर्ने नोटबुक ट्रेनमा छोडेर आए।","だけでは十分[じゅうぶん]ではない সীমা দেখাচ্ছে; কোনো ব্যাখ্যাই প্রয়োজন নেই বলা হয়নি।":"だけでは十分[じゅうぶん]ではない ले सीमा देखाउँछ; कुनै व्याख्या नै आवश्यक छैन भनिएको छैन।","এই পরিস্থিতিতে “কঠিন” কথাটি পরদিনের অনুরোধ প্রত্যাখ্যান করছে।":"यो अवस्थामा \"कठिन\" भन्ने कुराले अर्को दिनको अनुरोध अस्वीकार गर्दैछ।","অর্থ বুঝতে শব্দের পাশাপাশি প্রসঙ্গও জরুরি।":"अर्थ बुझ्न शब्दसँगै प्रसंग पनि जरुरी छ।","そこで আগের তথ্যের ভিত্তিতে করা পদক্ষেপকে যুক্ত করছে।":"そこで ले अघिल्लो जानकारीको आधारमा गरिएको कदमलाई जोड्दैछ।","মিনাকে এক বন্ধু বলল, “আবার বেড়াতে এসো।”":"मिनालाई एक साथीले भन्यो, \"फेरि घुम्न आउनुहोस्।\"","にすぎない পরিসরের সীমাবদ্ধতা দেখায়।":"にすぎない ले दायराको सीमा देखाउँछ।","একটি লাইব্রেরিতে বই খুঁজতে বেশি সময় লাগে বলে মতামত এসেছিল।":"एउटा पुस्तकालयमा किताब खोज्न बढी समय लाग्छ भनेर मत आएको थियो।","শুরুতে ব্যবহারকারীর সমস্যা তুলে ধরা হয়েছে।":"सुरुमा प्रयोगकर्ताको समस्या उठाइएको छ।","১২÷২০×১০০=৬০; শুধু সংখ্যা নয়, মোটের ভিত্তি দেখুন।":"१२÷२०×१००=६०; मात्र संख्या होइन, कुलको आधार हेर्नुहोस्।","তবে শুধু এই ফল দিয়ে জাপানের সব শিক্ষার্থী সম্পর্কে বলা যায় না।":"तर मात्र यो परिणामले जापानका सबै विद्यार्थीबारे भन्न सकिँदैन।","যেমন, প্রথমবার আসা ব্যক্তিকে ব্যবহারের পদ্ধতি দিয়ে বোঝানো শুরু করেন।":"जस्तै, पहिलो पटक आएका व्यक्तिलाई प्रयोगको तरिकाबाट बुझाउन सुरु गर्छन्।"},"study.reading_title":{"“একটু কঠিন” কথাটির পর কী হলো":"“अलि गाह्रो” भन्ने कुरापछि के भयो","সমস্যার বদলে প্রয়োজন থেকে ভাবা":"समस्याको सट्टा आवश्यकताबाट सोच्ने","ভালো সেবা মানে একই উত্তর নয়":"राम्रो सेवा भनेको एउटै उत्तर होइन","একটি আমন্ত্রণ, দুই রকম ধারণা":"एउटा निमन्त्रणा, दुई प्रकारका धारणा","হারানো খাতার ছোট গল্প":"हराएको नोटबुकको सानो कथा","জরিপের সংখ্যা থেকে কতটুকু বলা যায়":"सर्वेक्षणको सङ्ख्याबाट कति भन्न सकिन्छ"},"study.strategy":{"শব্দের আক্ষরিক অর্থের পাশাপাশি কে, কাকে, কোন অনুরোধে বলছে তা দেখুন। পরোক্ষ কথাকে সবার জন্য স্থির নিয়ম হিসেবে ধরবেন না।":"शब्दको शाब्दिक अर्थसँगै कसले, कसलाई, कुन अनुरोधमा भन्दैछ त्यो हेर्नुहोस्। अप्रत्यक्ष कुरालाई सबैका लागि स्थिर नियमको रूपमा नलिनुहोस्।","শিরোনাম ও ছোট উপশিরোনাম দেখে যুক্তির ধাপ ধরুন। দাবি, কারণ, উদাহরণ ও বিকল্পকে আলাদা করুন। মতের বিরোধিতা করলে কারণসহ বিকল্প দিন।":"शीर्षक र साना उपशीर्षक हेरेर तर्कको चरण समात्नुहोस्। दाबी, कारण, उदाहरण र विकल्पलाई अलग गर्नुहोस्। मतको विरोध गरेमा कारणसहित विकल्प दिनुहोस्।","চরিত্রের অনুভূতি কোন ঘটনা বা শব্দে বদলেছে তা দেখুন। উপমাকে বাস্তব ঘটনা হিসেবে নেবেন না। পর্যালোচনায় নিজের মূল্যায়নের কারণ দিন।":"पात्रको अनुभूति कुन घटना वा शब्दमा बदलिएको छ त्यो हेर्नुहोस्। उपमालाई वास्तविक घटनाको रूपमा नलिनुहोस्। समीक्षामा आफ्नो मूल्याङ्कनको कारण दिनुहोस्।","প্রশ্নের উত্তরে বক্তা প্রথমে সিদ্ধান্ত বলেছেন, না উদাহরণ দিয়েছেন, তা ধরুন। উদাহরণ কোন মূল কথাকে বোঝাচ্ছে সেটি খুঁজুন।":"प्रश्नको उत्तरमा वक्ताले पहिले निष्कर्ष भन्नुभयो, वा उदाहरण दिनुभयो, त्यो समात्नुहोस्। उदाहरणले कुन मूल कुरा बुझाउँदैछ त्यो खोज्नुहोस्।","বাক্যে কর্তা বাদ গেলে আগের বাক্য ও কথোপকথনের প্রবাহ দেখুন। অনুমান আর স্পষ্টভাবে বলা তথ্য আলাদা রাখুন।":"वाक्यमा कर्ता छुटेमा अघिल्लो वाक्य र वार्तालापको प्रवाह हेर्नुहोस्। अनुमान र स्पष्ट रूपमा भनिएको जानकारी अलग राख्नुहोस्।","জরিপের লক্ষ্যগোষ্ঠী, মোট উত্তরদাতা, সময় ও শতাংশের ভিত্তি আগে পড়ুন। উদাহরণের সংখ্যাকে বাস্তব জরিপের ফল হিসেবে ব্যবহার করবেন না।":"सर्वेक्षणको लक्षित समूह, कुल उत्तरदाता, समय र प्रतिशतको आधार पहिले पढ्नुहोस्। उदाहरणको संख्यालाई वास्तविक सर्वेक्षणको परिणामको रूपमा प्रयोग नगर्नुहोस्।"},"study.vocab":{"প্রকাশভঙ্গি":"अभिव्यक्ति शैली","দৃষ্টিকোণ":"दृष्टिकोण","ভুল বোঝাবুঝি":"गलत बुझाइ","অনুভূতি":"भावना","আস্থা":"विश्वास","উদ্বেগ":"चिन्ता","অভিজ্ঞতা":"अनुभव","লক্ষ্যগোষ্ঠী বা বিষয়":"लक्षित समूह वा विषय","জরিপ বা অনুসন্ধান":"सर्वेक्षण वा अनुसन्धान","অনুপাত":"अनुपात","উদ্দেশ্য":"उद्देश्य","অন্যের কথা বিবেচনা":"अरूको कुरा विचार","প্রসঙ্গ":"प्रसंग","ভূমিকা":"भूमिका","সংকোচ বা সংযম":"संकोच वा संयम","চিন্তার সূচনা বা ধারণা":"सोचको सुरुवात वा धारणा","পারস্পরিক আদানপ্রদান":"पारस्परिक आदानप्रदान","কৌশল বা বুদ্ধিদীপ্ত চেষ্টা":"कौशल वा बुद्धिमानी प्रयास","সহযোগিতা":"सहयोग","চাহিদা বা আশা":"माग वा आशा","ভিন্ন সংস্কৃতি":"फरक संस्कृति","প্রস্তাব":"प्रस्ताव","অভ্যাস বা রীতি":"बानी वा रीति","স্বস্তি":"राहत","গ্রাহকসেবা":"ग्राहक सेवा","হ্রাস":"ह्रास","মনের ওপর ছাপ":"मनमा छाप","বৃদ্ধি":"वृद्धि","তুলনা":"तुलना","গল্প বা আখ্যান":"कथा वा आख्यान","দৃশ্য বা পরিস্থিতি":"दृश्य वा अवस्था","যাচাই করা":"जाँच गर्नु","প্রত্যাখ্যান করা":"अस्वीकार गर्नु","উন্নতি":"उन्नति","জানানো":"जनाउनु"},"study.writing":{"আমি খাতা হারানো একজনের ছোট গল্প পড়েছি।":"मैले नोटबुक हराएका एकजनाको सानो कथा पढेको छु।","ট্রেন ব্যবহারকারী ১২ জন, যা সবচেয়ে বড় অংশ।":"ट्रेन प्रयोगकर्ता १२ जना छन्, जुन सबैभन्दा ठूलो भाग हो।","কিন্তু বন্ধু ভেবেছিল এখনো আলোচনা দরকার।":"तर साथीले सोचेको थियो अझै छलफल आवश्यक छ।","আমারও প্রিয় জিনিস হারানোর অভিজ্ঞতা আছে বলে অনুভূতিটি বুঝেছি।":"मेरो पनि प्रिय सामान हराउने अनुभव छ भनेर अनुभूति बुझेको छु।","অনুশীলনের জরিপে একটি ক্লাসের ২০ শিক্ষার্থীকে প্রশ্ন করা হয়েছে।":"अभ्यासको सर्वेक्षणमा एउटा कक्षाका २० विद्यार्थीलाई प्रश्न गरिएको छ।","এই অভিজ্ঞতার পর গুরুত্বপূর্ণ বিষয় স্পষ্টভাবে বলে নিশ্চিত করার চেষ্টা করি।":"यो अनुभवपछि महत्त्वपूर्ण विषय स्पष्ट रूपमा भनेर निश्चित गर्ने प्रयास गर्छु।","মূল চরিত্রের উদ্বেগ পরিচিত ভাষায় তুলে ধরা হয়েছে।":"मूल पात्रको चिन्ता परिचित भाषामा उठाइएको छ।","যেমন কঠিন শব্দ পরিচিত প্রকাশে বদলে দেওয়া যায়।":"जस्तै कठिन शब्द परिचित अभिव्यक्तिमा बदल्न सकिन्छ।","তাই যারা ব্যবহার করবেন তাঁদের মতামত শোনা উচিত বলে মনে করি।":"त्यसैले जसले प्रयोग गर्नुहुन्छ उनीहरूको मत सुन्नुपर्छ जस्तो लाग्छ।","এটি এমন গল্প যা দৈনন্দিন ছোট ঘটনাকেও গুরুত্ব দিতে শেখায়।":"यो यस्तो कथा हो जसले दैनिक साना घटनालाई पनि महत्त्व दिन सिकाउँछ।","আমি ভেবেছিলাম সময় ঠিক হয়ে গেছে।":"मैले सोचेको थिएँ समय तय भइसक्यो।","সম্পর্ক ও পরিস্থিতি অনুযায়ী তা বদলায়।":"सम्बन्ध र अवस्था अनुसार त्यो बदलिन्छ।","আমার মতে নির্দেশনা তৈরির সময় ব্যবহারকারীর দৃষ্টিকোণ জরুরি।":"मेरो मतमा निर्देशन बनाउने समयमा प्रयोगकर्ताको दृष्टिकोण जरुरी छ।","দীর্ঘ অভিজ্ঞতার ভিত্তিতে তিনি বোঝানোর ধরনে কৌশল ব্যবহার করেন।":"लामो अनुभवको आधारमा उनले बुझाउने शैलीमा कौशल प्रयोग गर्छन्।","তাঁর মতে সবচেয়ে গুরুত্বপূর্ণ হলো গ্রাহকের কথা শোনা।":"उनका अनुसार सबैभन्दा महत्त्वपूर्ण भनेको ग्राहकको कुरा सुन्नु हो।","আমি পাশের দোকানের ম্যানেজারের সাক্ষাৎকার নিয়েছি।":"मैले छेउको पसलका म्यानेजरको अन्तर्वार्ता लिएको छु।","জাপানিতে কোনো সময় না করার আগে কারণ বলা হয়।":"जापानीमा कुनै समय नगर्नुअघि कारण भनिन्छ।","না বুঝলে আমি ভদ্রভাবে নিশ্চিত হতে চাই।":"नबुझेमा म विनम्र रूपमा निश्चित हुन चाहन्छु।","আমিও অন্যের অবস্থান বিবেচনা করে কাজ করতে চাই বলে মনে হয়েছে।":"मलाई पनि अरूको स्थान विचार गरेर काम गर्न चाहन्छु जस्तो लागेको छ।","তবে সবসময় একই প্রকাশ ব্যবহার হয় না।":"तर सधैं एउटै अभिव्यक्ति प्रयोग हुँदैन।","জাপানে নতুন আসার সময় এক বন্ধুর সঙ্গে কথা দেওয়া নিয়ে সমস্যায় পড়েছিলাম।":"जापानमा नयाँ आएको समयमा एक साथीसँग वाचा दिने विषयमा समस्यामा परेको थिएँ।","সাইকেল ব্যবহারকারীর তুলনায় ৭ জন বেশি।":"साइकल प्रयोगकर्ताको तुलनामा ७ जना बढी छन्।","কারণ তথ্য বেশি হলেই অর্থ পরিষ্কার হয় এমন নয়।":"कारण जानकारी बढी हुँदैमा अर्थ स्पष्ट हुन्छ भन्ने होइन।","তবে অল্পসংখ্যক ব্যক্তির ফল বলে এটি সামগ্রিক প্রবণতা নাও হতে পারে।":"तर थोरै संख्याका व्यक्तिको परिणाम भएकाले यो समग्र प्रवृत्ति नहुन पनि सक्छ।"},"study.writing_prompt":{"নিজের একটি ভুল বোঝাবুঝির অভিজ্ঞতা লিখুন: ঘটনা → নিজের ধারণা → অন্য পক্ষের অবস্থা → পরেরবার কী করবেন।":"आफ्नो एउटा गलत बुझाइको अनुभव लेख्नुहोस्: घटना → आफ्नो धारणा → अर्को पक्षको अवस्था → अर्को पटक के गर्नुहुन्छ।","বাংলা ও জাপানিতে কোনো অনুরোধ ফিরিয়ে দেওয়ার একটি করে উদাহরণ দিন। শব্দের অর্থ, সম্পর্ক ও পরিস্থিতি আলাদা করে লিখুন; জাতিগত সাধারণীকরণ এড়িয়ে চলুন।":"नेपाली र जापानीमा कुनै अनुरोध फिर्ता गर्ने एक एक उदाहरण दिनुहोस्। शब्दको अर्थ, सम्बन्ध र अवस्था अलग गरेर लेख्नुहोस्; जातिगत सामान्यीकरणबाट बच्नुहोस्।","একটি গল্প বা সিনেমার সংক্ষিপ্ত রিভিউ লিখুন: পরিচয় → একটি দৃশ্য → নিজের অনুভূতি → সুপারিশের কারণ। সমাপ্তির সব তথ্য বলে দেবেন না।":"एउटा कथा वा चलचित्रको संक्षिप्त समीक्षा लेख्नुहोस्: परिचय → एउटा दृश्य → आफ्नो अनुभूति → सिफारिसको कारण। अन्त्यको सबै जानकारी नभन्नुहोस्।","এই কাল্পনিক সংখ্যাগুলো ব্যবহার করে চার বাক্যের প্রতিবেদন লিখুন। লক্ষ্যগোষ্ঠী → সবচেয়ে বড় অংশ → তুলনা → সিদ্ধান্তের সীমা।":"यी काल्पनिक संख्याहरू प्रयोग गरेर चार वाक्यको प्रतिवेदन लेख्नुहोस्। लक्षित समूह → सबैभन्दा ठूलो भाग → तुलना → निष्कर्षको सीमा।","একটি ছোট সমস্যা বেছে ১৮০–২৫০ জাপানি অক্ষরে মতামত লিখুন: দাবি → কারণ → উদাহরণ → সম্ভাব্য আপত্তি → বাস্তব প্রস্তাব।":"एउटा सानो समस्या रोजेर १८०–२५० जापानी अक्षरमा मत लेख्नुहोस्: दाबी → कारण → उदाहरण → सम्भाव्य आपत्ति → वास्तविक प्रस्ताव।","কোনো পরিচিত ব্যক্তির কাজ সম্পর্কে তিনটি প্রশ্ন করুন। সরাসরি উক্তি এবং নিজের উপলব্ধি আলাদা করে একটি ছোট প্রতিবেদন লিখুন।":"कुनै परिचित व्यक्तिको कामबारे तीन प्रश्न गर्नुहोस्। सीधा भनाइ र आफ्नो बोध अलग गरेर एउटा सानो प्रतिवेदन लेख्नुहोस्।"},"title":{"QUARTET II · বাংলা গ্রামার সহায়িকা":"QUARTET II · नेपाली व्याकरण सहयोगी"}},"qa":{"attr.aside@aria-label":{"পাঠ নির্বাচন":"पाठ छनोट"},"attr.div@aria-label":{"পড়ার ধরন":"पढाइको प्रकार"},"attr.input@aria-label":{"গ্রামার খুঁজুন":"व्याकरण खोज्नुहोस्"},"attr.meta@description":{"QUARTET Ⅱ-এর অধ্যায় ৭–১২-এর থিমে নির্বাচিত ৩৬টি বিষয়ে নিজস্ব বাংলা ব্যাখ্যা, ফুরিগানাসহ উদাহরণ ও অনুশীলন।":"QUARTET Ⅱ-को अध्याय 7–12-को विषयवस्तुमा छनोट गरिएका 36 वटा विषयमा आफ्नै नेपाली व्याख्या, फुरिगानासहित उदाहरण र अभ्यास।"},"attr.nav@aria-label":{"এই অধ্যায়ের গ্রামার":"यो अध्यायको व्याकरण","QUARTET বই ও পড়ার ধরন":"QUARTET पुस्तक र पढ्ने तरिका","পথ নির্দেশনা":"बाटो निर्देशन"},"attr.progress@aria-label":{"গ্রামার শেখার অগ্রগতি":"व्याकरण सिकाइको प्रगति"},"text.uncovered":{"পাঠ ও অনুশীলন খুলতে JavaScript চালু করুন।":"पाठ र अभ्यास खोल्न JavaScript सक्षम गर्नुहोस्।","N2 Grammar পড়ুন":"N2 Grammar पढ्नुहोस्"}}};
